/* Original challenge questions. Regenerate with authoring/challenge/build.py. */
window.CHALLENGE_EXAMS=[{"id":"challenge-1","name":"Challenge Exam 1","questions":[{"id":"CH1-001","objective":"1.1","concept":"Compensating control scope","prompt":"A legacy payroll appliance cannot enforce MFA. An approved exception requires access through a separately authenticated gateway and a daily access review until replacement. Which description BEST explains these added measures relative to the MFA requirement?","options":["Corrective controls","Compensating controls","Directive controls","Deterrent controls"],"explanations":["They restrict and review access rather than repair damage after an incident.","They reduce the risk of an unmet primary requirement during an approved exception.","The exception is documented, but the added gateway and reviews do more than issue instructions.","The measures enforce and inspect access rather than mainly discourage attempts."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-002","objective":"1.1","concept":"Control implementation category","prompt":"A nightly script identifies excessive permissions, but a supervisor manually investigates each report and authorizes removal. An assessor is classifying the supervisor's review itself. Which category fits BEST?","options":["Managerial","Technical","Operational","Physical"],"explanations":["The review executes a control; establishing its policy and risk requirements would be managerial.","The reporting script is technical; the question isolates the supervisor's activity.","The assessed activity is a recurring human review, even though software supplies its input.","No facility, equipment-access, or environmental safeguard is being classified."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-003","objective":"1.2","concept":"Zero trust decision versus enforcement","prompt":"A device loses its managed status during an active session. A central service reevaluates policy and sends a deny decision, but the application connection stays open. Which component MOST directly failed to apply that decision?","options":["Identity provider","Policy engine","Policy administrator, assuming its deny instruction was successfully delivered","Policy enforcement point"],"explanations":["An identity can remain valid while device posture makes the existing session unauthorized.","The engine has already reevaluated the context and produced the deny decision.","The specified instruction reached enforcement; the continued connection points to failure to apply it.","The policy enforcement point must actually terminate or deny the connection."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-004","objective":"1.2","concept":"Integrity versus source authenticity","prompt":"An attacker replaces a software archive and its unsigned checksum on the same download server. Both now match. What additional check would BEST let a customer detect the unauthorized replacement?","options":["Verify the publisher's digital signature using a trusted public key","Verify a checksum obtained from the same server over a second connection","Confirm that the download server presents a valid TLS certificate","Validate that the archive's embedded unsigned manifest matches its files"],"explanations":["The attacker cannot create a valid publisher signature without the corresponding private key.","A second connection to the compromised source does not independently authenticate its checksum.","TLS authenticates the server connection, not whether its stored archive was maliciously replaced.","An attacker able to rebuild the archive can replace its unsigned manifest too."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-005","objective":"1.2","concept":"Deception evidence","prompt":"A monitored credential is placed in a configuration file but is not assigned to any legitimate service. A login using it occurs from a build worker. What is the STRONGEST justified conclusion?","options":["The build worker's administrator deliberately stole the credential","The decoy credential was obtained and used from that worker","The login proves the production database was exfiltrated","The credential must have been guessed through password spraying"],"explanations":["A process or compromised account could have used it without the administrator's involvement.","A honeytoken's use is high-signal evidence, but it does not establish the complete intrusion path.","Use of a decoy alone does not establish production data access or exfiltration.","The token's use does not determine whether it was guessed or read."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-006","objective":"1.3","concept":"Dependency-aware change control","prompt":"A TLS hardening change passes web-browser tests. Before approval, the application owner identifies a nightly importer that uses an older protocol. What should happen NEXT?","options":["Exclude the importer from the hardening rule without documenting an exception","Approve the change with a backout plan because any failure can be reversed","Test the importer dependency and revise the impact and backout plans","Ask the service desk to warn users and keep the existing test results"],"explanations":["A compatibility workaround still requires assessed and authorized risk handling.","Rollback readiness helps, but does not replace assessing the newly identified dependency.","The newly identified dependency changes the evidence needed to approve a safe deployment.","Notification does not validate a dependent workload omitted from testing."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-007","objective":"1.3","concept":"Backout feasibility","prompt":"A release changes an application and irreversibly transforms its database schema. The backout plan only reinstalls the previous application binaries. What is the MOST important gap?","options":["Require the database owner to sign the existing backout plan","Preserve the prior binaries and their hashes in a second repository","Increase the monitoring window to catch incompatible queries earlier","A tested way to restore compatible data and schema"],"explanations":["Approval cannot make a technically incomplete recovery method work.","That protects application artifacts but still cannot undo incompatible data transformation.","Earlier detection does not create a viable database recovery path.","Old binaries may not work with transformed data, so rollback must address both."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-008","objective":"1.4","concept":"Certificate chain diagnosis","prompt":"A service presents an unexpired certificate for the correct hostname. New clients fail trust validation, but older clients with a cached intermediate succeed. What is the BEST server-side correction?","options":["Install the missing intermediate certificate in the served chain","Add the service hostname to the certificate's subject alternative names","Replace the root certificate in every client's trust store","Publish a newer certificate revocation list at the server"],"explanations":["The different cache states point to an incomplete certificate chain.","The existing certificate already matches the hostname.","The difference is the cached intermediate, not evidence that the root itself is untrusted.","Revocation freshness does not supply the missing intermediate issuer certificate."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-009","objective":"1.4","concept":"Salting versus stretching","prompt":"A breach exposes salted password hashes. Identical passwords have different hashes, but an attacker still tests billions of guesses per second. Which change MOST directly addresses the remaining weakness?","options":["Increase the salt length while keeping the same fast hash algorithm","Use a password-hashing function with an appropriate work factor","Encrypt password-reset links with the database's storage key","Use a different fast hash function for each account"],"explanations":["Unique salts prevent shared precomputation; lengthening them does not substantially slow each guess.","Key stretching increases the cost of each password guess; unique salts alone do not.","Reset-link protection does not strengthen the exposed password hashes.","Algorithm variation is not a substitute for a deliberately expensive password-hashing function."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-010","objective":"1.4","concept":"Cryptographic erasure prerequisites","prompt":"A retired encrypted storage array cannot be physically destroyed. Which condition is MOST important before relying on cryptographic erasure?","options":["The key-management system has renamed the old key as retired","The storage controller reports that a quick format completed successfully","All copies of the relevant decryption keys can be irretrievably destroyed","The original array is removed from the online storage inventory"],"explanations":["A retired label does not demonstrate that the key material and recoverable copies are gone.","A quick format can remove metadata while leaving decryptable content and keys.","Remaining escrowed or backed-up keys can make the supposedly erased data recoverable.","Inventory removal does not make retained media and keys unrecoverable."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-011","objective":"1.4","concept":"Revocation freshness tradeoff","prompt":"A disconnected field appliance validates a vendor certificate using a locally cached revocation list. The certificate was revoked yesterday, after the last list update. Why might verification still succeed?","options":["A cached list is guaranteed to contain revocations announced after its issue time","Its valid certificate signature overrides all later revocation decisions","The issuing authority cannot revoke a certificate before its expiration date","Its available revocation information predates the revocation"],"explanations":["A static cached list cannot contain future revocations it has not received.","Signature validity and revocation status are separate checks; one does not override the other.","An authority can revoke a still-unexpired certificate.","An offline check cannot discover a revocation absent from its cached CRL, or certificate revocation list."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-012","objective":"1.4","concept":"Key escrow boundaries","prompt":"A business wants to recover employees' encrypted work files without giving the recovery team the ability to impersonate employees when signing approvals. Which design BEST meets both goals?","options":["Escrow encryption recovery keys while keeping signing keys separate","Escrow a single employee key for both decryption and signing, with recovery logging","Share the employee's private signing key only with two recovery operators","Archive only the encryption certificates without the corresponding recovery secret"],"explanations":["Separating key purposes enables data recovery without granting signing authority.","Audit logs reveal usage but do not prevent a key holder from producing employee signatures.","Limiting holders still grants those operators the ability to sign as that employee.","Public certificates alone do not provide the private material needed for recovery."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-013","objective":"2.1","concept":"Attribution limits","prompt":"An intrusion uses an expensive exploit, persists for months, and collects defense research without demanding payment. Which assessment is MOST defensible from these facts alone?","options":["The actor is certainly a foreign government rather than a contractor","Espionage is a likely motivation, but actor identity remains unconfirmed","The actor must be an insider because access persisted for months","Financially motivated crime is proven by the exploit's cost"],"explanations":["Sophistication and targets alone do not conclusively identify the responsible organization.","The behavior supports a motive assessment without proving attribution to a specific actor.","External intruders can maintain persistence using compromised systems and accounts.","The cost of tooling does not establish the objective of the operation."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-014","objective":"2.1","concept":"Shadow IT responsibility","prompt":"A sales manager uploads customer exports to an unapproved AI service to meet a deadline. There is no evidence of malicious intent or account compromise. Which classification BEST describes the immediate issue?","options":["A confirmed malicious insider operation based on the upload alone","An authorized outsourcing arrangement based on the manager's existing data access","Shadow IT creating unmanaged data exposure","A processor control failure under an already approved vendor agreement"],"explanations":["The facts identify unauthorized service use but explicitly do not establish malicious intent.","Permission to read data does not automatically authorize use of an unapproved processor.","Authorized staff are using an unapproved service outside security oversight.","No approved processing arrangement has been established."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-015","objective":"2.2","concept":"Supplier compromise pathway","prompt":"A remote-support vendor's valid signing key is abused to distribute a modified agent through its normal updater. Which added safeguard BEST addresses this pathway beyond signature verification alone?","options":["Permit updates only from the vendor's established distribution domains","Accept signed updates only when the vendor's certificate is unexpired","Compare each downloaded update with the hash published by that same updater","Stage updates and monitor their behavior before broad rollout"],"explanations":["The attacker is using the normal vendor distribution path.","The described malicious update already has a valid signature using abused signing credentials.","A compromised distribution process can publish a matching hash for its malicious update.","A legitimate signature cannot establish that a compromised publisher's code is benign."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-016","objective":"2.2","concept":"Watering-hole targeting","prompt":"Only engineers who visit a specialized component-specification portal become infected. The portal is legitimate but now serves a malicious script; no messages were sent to them. Which vector BEST fits?","options":["Watering-hole attack","Spear-phishing campaign","Typosquatting campaign","Business email compromise"],"explanations":["The attacker compromised a site the intended victims already frequent.","Targeting exists, but there is no deceptive message leading users to the site.","The victims used the legitimate portal, not a look-alike misspelled domain.","No business mailbox or email transaction is involved in the evidence."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-017","objective":"2.2","concept":"Out-of-band verification","prompt":"An accounts-payable clerk receives a real supplier email thread requesting a new payment account. The message passes email authentication. Which action BEST addresses the remaining fraud risk?","options":["Ask the sender to confirm the bank change in a new email thread","Confirm the change using a previously verified supplier phone number","Validate DKIM and the sender's normal domain before changing the payment account","Require the sender to attach an updated invoice using the usual template"],"explanations":["A compromised supplier mailbox can answer new threads too.","A compromised real mailbox can send authenticated mail; independent verification checks the business request.","DomainKeys Identified Mail does not prove a real mailbox's business request is legitimate.","An attacker in the existing thread can reproduce normal supporting documents."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-018","objective":"2.2","concept":"Attack surface reduction","prompt":"An internet-facing administration page uses strong passwords but no business process requires remote administration. Which change MOST directly removes that exposure?","options":["Rename the management URL and remove it from public links","Restrict login attempts and require phishing-resistant MFA on the public page","Disable public access to the management interface","Place the same public management page behind a WAF"],"explanations":["An undisclosed URL can still be found and reached.","Those reduce login risk but leave an unnecessary interface and its software vulnerabilities exposed.","Removing unnecessary exposure eliminates that internet attack path.","A web application firewall can mitigate some attacks, but does not eliminate unnecessary public exposure."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-019","objective":"2.3","concept":"Race condition evidence","prompt":"A service checks that a temporary file belongs to a standard user. Before the privileged service writes to it, the user substitutes a link to a protected file. Which weakness enabled the write?","options":["A symbolic-link vulnerability with no timing-dependent validation gap","Improper bounds checking during copying into a fixed-size buffer","A direct permission bypass during the initial ownership check","Time-of-check to time-of-use race condition"],"explanations":["The described exploit specifically depends on changing the reference between check and use.","The weakness is target substitution between operations, not an oversized write.","The check succeeded for the original file; the target changed afterward.","The trusted condition changed between validation and the later privileged operation."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-020","objective":"2.3","concept":"Stored versus reflected scripts","prompt":"A forum safely parameterizes database queries, but saved posts can still execute script when rendered in a reader's browser. Which control MOST directly addresses the remaining flaw?","options":["Context-appropriate output encoding when rendering untrusted post content","Parameterize the database queries again using a different SQL driver","Require TLS for the page while keeping the same rendering behavior","Reject only posts containing a literal lowercase script tag"],"explanations":["Encoding prevents saved content from being interpreted as executable markup in the relevant output context.","SQL safety does not automatically make retrieved text safe for browser rendering.","Encrypted delivery still delivers executable attacker content to the browser.","A narrow deny list is brittle and misses other executable contexts and encodings."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-021","objective":"2.3","concept":"Virtualization boundary","prompt":"A hypervisor flaw lets a hostile guest affect neighboring guests. All guests have current operating-system patches. A maintenance window is approved. Which action MOST directly remediates the shared boundary weakness?","options":["Reinstall each guest from the same approved image without updating the host","Patch the vulnerable hypervisor and verify the updated host state","Put each guest on a separate VLAN while leaving the host code unchanged","Encrypt guest virtual disks using separate keys without updating the host"],"explanations":["The vulnerable hypervisor remains beneath the fresh guests.","Guest patching does not repair a defect in the host isolation layer.","Network segmentation does not repair an exploit through the virtualization layer.","Storage encryption does not fix the hypervisor's guest-isolation failure."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-022","objective":"2.3","concept":"Unsigned firmware risk","prompt":"A device accepts a modified boot image even though its operating system packages are fully patched. Which missing protection is MOST relevant?","options":["Enable full-disk encryption without checking the boot chain","Apply application allowlisting only after the operating system starts","Cryptographic verification of firmware before execution","Monitor operating system package hashes against the approved baseline"],"explanations":["Encryption protects stored data but does not by itself authenticate every firmware image.","A post-boot application policy does not establish trust in firmware already executed.","Validated boot firmware prevents unauthorized images from being accepted simply as executable code.","That can miss unauthorized code below the operating system."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-023","objective":"2.3","concept":"Unnecessary privilege vulnerability","prompt":"A low-privilege web service can write into a directory from which a scheduled privileged task loads scripts. What is the MOST direct corrective action?","options":["Move the scheduled task to a later maintenance window","Run the web service under a renamed account with the same permissions","Sign the scheduled task's logs but leave script loading unchanged","Remove the web service's write permission on the trusted script directory"],"explanations":["Rescheduling leaves the same permission and trust-boundary defect.","The writable trusted-code directory remains exploitable.","Log integrity does not prevent privileged execution of replaced scripts.","This closes the trust-boundary failure enabling replacement of privileged code."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-024","objective":"2.4","concept":"Credential stuffing evidence","prompt":"A retailer sees a login campaign from rotating addresses. To distinguish credential stuffing from password spraying, which additional evidence is MOST useful?","options":["Whether attempts reuse distinct breached credential pairs or a small shared password set","Whether source addresses belong to several different countries","Whether some targeted usernames are valid accounts","Whether successful sessions use HTTPS"],"explanations":["The credential pattern distinguishes reuse of leaked pairs from spraying a few guesses across users.","Either technique can use distributed infrastructure.","Both attacks may target valid users.","Transport encryption does not distinguish how the attacker selected the credentials."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-025","objective":"2.4","concept":"DNS tunneling evidence","prompt":"A workstation makes thousands of DNS queries with long, changing subdomain labels to one newly registered domain. Responses are small, and ordinary browsing remains normal. What should an analyst investigate FIRST?","options":["A large inbound file transfer encoded mainly in DNS response payloads","Possible data transfer encoded in DNS query names","Ordinary high-volume resolution of many unrelated popular websites","An attempt to poison cached answers for the company's existing domain"],"explanations":["Small responses and changing long query labels more strongly suggest query-side outbound transfer.","Changing high-entropy labels can carry outbound data even when answers are small.","The stable newly registered parent domain and changing encoded labels make this less consistent.","The evidence describes repeated queries to an attacker-like domain, not forged authoritative answers."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-026","objective":"2.4","concept":"Pass-the-hash evidence","prompt":"After a workstation compromise, an attacker authenticates to another Windows host using captured NTLM material without recovering the password's plaintext. Which technique BEST fits?","options":["Password spraying","Kerberoasting","Pass-the-hash","Offline dictionary cracking followed by a normal password login"],"explanations":["Spraying tests a small password set against many accounts rather than reusing captured hashes.","That targets Kerberos service-ticket material for offline password cracking, unlike replaying captured NTLM material.","Captured password-derived authentication material is reused without knowing the original password.","The attacker explicitly did not recover the plaintext password before authenticating."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-027","objective":"2.4","concept":"Malware trigger distinction","prompt":"A departing developer leaves code that deletes records only when the developer's account disappears from the employee directory. Which malware characteristic is MOST specific?","options":["Rootkit","Worm","Ransomware","Logic bomb"],"explanations":["The trigger does not establish stealthy modification of operating system internals.","Nothing indicates autonomous propagation to other systems.","Deletion is conditional, but encryption or an extortion demand is not described.","Execution is tied to a deliberately chosen logical condition."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-028","objective":"2.4","concept":"Malicious versus authorized scripting","prompt":"An endpoint alert shows a document reader launching a command interpreter, which then downloads and executes an unsigned script. The device has no approved automation role. What makes this chain MOST suspicious?","options":["An unexpected parent-child process chain leading to remote code execution","The mere use of a native interpreter instead of a third-party executable","The use of TLS for the download rather than an unencrypted transfer","The lack of a persistent executable saved in the normal download directory"],"explanations":["The combined process relationships and download behavior are stronger evidence than one tool name alone.","Native interpreters have legitimate uses; the chain and context make this suspicious.","Both legitimate and malicious downloads can use encrypted transport.","A file's location or absence alone is weaker than the observed execution chain."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-029","objective":"2.4","concept":"Layer seven availability attack","prompt":"A web service has normal network bandwidth but exhausted application workers. Thousands of clients repeatedly request an expensive report requiring database joins. Which mitigation is MOST targeted?","options":["Add a larger internet connection while leaving request processing unchanged","Rate-limit the expensive endpoint and apply application-aware request controls","Use a packet filter that permits all established connections on the web port","Cache only static site images while leaving report generation unrestricted"],"explanations":["Bandwidth is normal; the application workers are exhausted.","The resource exhaustion occurs in application work, so controls must address those requests.","The expensive requests can travel inside otherwise valid established sessions.","That does not address the resource-intensive dynamic endpoint."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-030","objective":"2.4","concept":"RFID replay risk","prompt":"A facility badge identifier is copied to another token, and both tokens open the same door. Disabling the original badge also disables the copy. What does this MOST strongly suggest?","options":["The second token relays live authentication to the original on each use","The access database issued separate revocable credentials to two people","The door system trusts a reproducible static credential identifier","The door authenticates physical possession using a nonexportable challenge-response secret"],"explanations":["A copied static identifier with matching access does not require a live relay, unlike that hypothesis.","The copied identifier and shared revocation instead indicate the same logical credential.","Both tokens represent the same logical credential rather than independently authenticated identities.","The described successful identifier copying suggests a weaker static credential check."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-031","objective":"2.5","concept":"Application allowlisting scope","prompt":"A kiosk must run a small fixed set of programs. Malware frequently changes its filename and hash, making blocklists ineffective. Which approach BEST reduces execution of unknown programs?","options":["Approve applications solely because their filenames match the standard inventory","Deny execution only when a file hash appears in current threat intelligence","Allow any program installed beneath a user-writable approved directory","Permit only explicitly approved applications under an allowlisting policy"],"explanations":["An attacker can reuse an approved filename without using approved code.","That retains the reactive hash-dependent approach defeated by new samples.","Path trust is ineffective when attackers can write new executables into that location.","An allowlist rejects unknown programs without needing every malicious filename or hash."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-032","objective":"2.5","concept":"Containment with business constraints","prompt":"A vendor-managed medical controller has an unpatched remote exploit. It must remain operating and cannot accept an endpoint agent. Which immediate mitigation BEST reduces exposure?","options":["Restrict its network paths to required peers and management sources","Allow access from the entire vendor network so support can observe failures","Place the controller in a different subnet while preserving unrestricted routing","Require console password changes while retaining the remotely exploitable service paths"],"explanations":["Segmentation reduces exploit reachability without modifying or shutting down the controller.","That can retain excessive exposure beyond the required management sources.","Address separation without restrictions does not limit exploit reachability.","Console credentials may not be involved in the remote exploit."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-033","objective":"2.5","concept":"Hardening service accounts","prompt":"A backup service needs read access to production data and write access to its backup repository. It currently has domain-admin rights. What change BEST preserves function while reducing compromise impact?","options":["Retain domain-admin membership but put the password in a managed vault","Assign only the required scoped permissions to a dedicated service identity","Use one highly privileged account for every backup application to simplify rotation","Grant the service read access to every domain and write access to every file share"],"explanations":["Better secret custody helps, but the account still has unnecessary authority.","Least privilege removes unrelated administrative reach while preserving backup operations.","Concentrated privilege increases compromise impact and weakens scope.","That remains much broader than the specified production data and backup repository."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-034","objective":"2.5","concept":"Removing persistence","prompt":"A compromised server has been isolated. Investigators find an unauthorized scheduled task that reinstalls malware after files are deleted. Which action belongs to eradication?","options":["Restore the most recent data backup without examining scheduled execution","Stop the running malware process and restore network access immediately","Remove the persistence mechanism and remediate the exploited weakness","Rotate user passwords while leaving the task and exploited software unchanged"],"explanations":["Restoring data does not remove a malicious recurring task.","The scheduled task can start the malware again.","Eradication must eliminate the mechanism that would restore the malicious code.","Credential changes alone do not eliminate this persistence and entry mechanism."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-035","objective":"3.1","concept":"Container isolation tradeoff","prompt":"Several mutually untrusted customers run containers on one host. Management assumes separate container images provide the same kernel isolation as separate VMs. Which concern BEST challenges that assumption?","options":["Read-only container filesystems prevent every host-kernel exploitation path","Each separate container image necessarily has its own dedicated kernel","A separate container network namespace eliminates all shared-kernel risk","The containers share the host kernel, increasing the impact of a kernel flaw"],"explanations":["Read-only filesystems do not eliminate kernel vulnerabilities.","Ordinary containers share the host kernel despite separate filesystems and processes.","Network namespaces do not remove the common kernel attack surface.","Separate images do not give each container a separately virtualized operating system kernel."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-036","objective":"3.1","concept":"Serverless responsibility","prompt":"A serverless function uses a role that can read every object in the company's cloud storage. An injection flaw lets an attacker invoke those reads. Which action remains the customer's responsibility?","options":["Reduce the function role to the storage objects it actually requires","Require the provider to change the function's business-data permissions without customer authorization","Rely on the provider's host patching to restrict which objects a valid role can read","Encrypt stored objects while allowing the same function role to decrypt all of them"],"explanations":["The customer configures application permissions even when the provider manages runtime infrastructure.","The customer must define and configure the appropriate application authorization scope.","Host patching does not replace authorization limits on a legitimate role.","That leaves the role's excessive data access intact."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-037","objective":"3.1","concept":"Infrastructure as code review","prompt":"A proposed infrastructure template opens a database port to the internet. The change is caught during review before any resource is created. Which benefit is MOST directly demonstrated?","options":["Source control alone prevents unauthorized changes to running resources","Security configuration can be evaluated before deployment","A successful template syntax check establishes least-privilege configuration","The reviewed template automatically overrides all later manual firewall edits"],"explanations":["Live changes can still cause drift unless separately controlled.","Infrastructure as code makes intended settings inspectable before they become live infrastructure.","Valid syntax can still define publicly exposed resources.","Automatic reconciliation requires actual enforcement; review alone does not provide it."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-038","objective":"3.1","concept":"Industrial safety constraint","prompt":"A factory wants to insert inline inspection into a deterministic control network. The proposed device may add variable latency. What is the BEST first design consideration?","options":["Assume an inline device's bypass mode always preserves both safety and confidentiality","Select the strongest inspection policy first and measure control timing after deployment","Validate control-loop timing and safe-failure behavior before deployment","Use average office-network latency as the acceptance criterion"],"explanations":["Failure modes need explicit assessment; bypass can sacrifice inspection and may not meet timing.","That risks introducing unsafe timing changes before validation.","Availability and safety constraints can make variable inspection delays unacceptable.","Deterministic control loops may need stricter bounds and predictable timing."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-039","objective":"3.2","concept":"Proxy placement and encryption","prompt":"A reverse proxy terminates external TLS and forwards unencrypted traffic across a shared internal segment to application servers. What change BEST addresses the exposed segment?","options":["Rotate the external certificate more frequently while leaving backend transport unchanged","Require mutual TLS only between internet clients and the reverse proxy","Place a passive IDS on the shared segment while retaining plaintext forwarding","Use authenticated TLS from the proxy to each backend"],"explanations":["Certificate rotation does not encrypt a different unprotected hop.","That strengthens the first hop but leaves the backend hop in plaintext.","Detection does not provide confidentiality for that segment.","Re-encryption protects the separate backend hop after external TLS termination."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-040","objective":"3.2","concept":"VPN route visibility","prompt":"A remote laptop sends business-app traffic through a VPN but routes public web traffic directly to its home router. The company requires central inspection of all internet browsing. Which change BEST meets that requirement?","options":["Use a full-tunnel VPN route with sufficient gateway inspection capacity","Advertise routes only for the company's internal subnets","Install the inspection sensor at the VPN concentrator without changing client routing","Strengthen the split tunnel's cipher and require device certificates"],"explanations":["A full tunnel brings internet-bound traffic to the central inspection point.","That is consistent with the split-routing behavior already missing public browsing.","Bypassed browsing never reaches that sensor.","Tunnel security does not change which destinations are routed through it."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-041","objective":"3.2","concept":"TLS visibility tradeoff","prompt":"A network sensor sees encrypted sessions to a payment service but no payloads. Inspection is required for managed clients, and organizational policy permits decryption at a controlled gateway. Which design provides the required visibility?","options":["Mirror encrypted traffic after the firewall rather than before it","Terminate and inspect TLS at an authorized proxy, then establish TLS onward","Inspect only certificate names and session sizes as if they were application contents","Require mutual TLS between clients and destinations while retaining passive-only monitoring"],"explanations":["Moving the observation point does not automatically decrypt the payload.","The proxy must access plaintext between two protected sessions to inspect application content.","Metadata can support detection but does not satisfy required payload visibility.","Mutual authentication alone does not grant a passive monitor access to plaintext."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-042","objective":"3.2","concept":"Management plane isolation","prompt":"Administrators can reach switch management interfaces from ordinary user VLANs. User workloads need no such access. Which design BEST reduces the risk from a compromised workstation?","options":["Restrict access only by source MAC address across routed networks","Permit management from all internal subnets but disable internet access","Use a dedicated management segment reachable only through approved administration paths","Enable encrypted management protocols while retaining unrestricted user-VLAN access"],"explanations":["A MAC address is not a reliable routed management authorization boundary.","That still exposes management to the compromised internal workstation in the scenario.","This limits management-plane reachability while preserving controlled administrative access.","Encryption protects the connection but does not remove unnecessary reachability."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-043","objective":"3.2","concept":"Fail-open versus fail-closed","prompt":"A document-signing gateway must never release documents that bypass signature validation. An outage may delay deliveries. Which failure behavior BEST matches this requirement?","options":["Release documents and perform retroactive validation once the service returns","Release documents signed by known users when validation is unavailable","Release documents after checking their filename against a trusted sender list","Fail closed and queue documents until validation is available"],"explanations":["Retroactive checking cannot satisfy the requirement to validate before release.","A known identity does not establish that a particular document's signature is valid.","Filename and sender familiarity are not signature validation.","Blocking release preserves the mandatory validation property at the cost of delay."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-044","objective":"3.3","concept":"Tokenization versus masking","prompt":"Support staff need to correlate repeated purchases using a stable substitute for a card number. They must never recover the card number; a separate payment service must still resolve it. Which design BEST fits?","options":["Tokenization with a separately controlled mapping service","Mask the displayed card number but leave the full number in the support API","Hash card numbers without keeping any restricted resolution mechanism","Encrypt numbers using a key supplied to every support client"],"explanations":["A stable token supports correlation while a restricted service controls reversal.","The underlying sensitive value remains available to support clients.","One-way hashes do not meet the payment service's requirement to resolve the original number.","Support clients with decryption keys could recover values they are forbidden to access."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-045","objective":"3.3","concept":"Data minimization boundary","prompt":"A test team needs realistic order relationships but has no need for real customer identities. Which dataset BEST reduces privacy risk while preserving the required relationships?","options":["Hash customer names but retain real email addresses and phone numbers","Synthetic identities with consistent replacement keys across related tables","Randomize join identifiers independently in each related table","Copy production identities unchanged and rely only on test-network isolation"],"explanations":["Other direct identifiers still expose real people unnecessarily.","Consistent synthetic identifiers retain joins without exposing real identities.","That reduces linkability but breaks the relationships the team requires.","That adds controls but retains sensitive data the test has no need to hold."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-046","objective":"3.3","concept":"Data in use exposure","prompt":"An analytics process decrypts sensitive records in memory. Disk encryption and HTTPS are enabled. A malicious process with sufficient memory-reading privileges extracts the plaintext. Which gap is demonstrated?","options":["The HTTPS certificate failed to protect application memory","The storage encryption algorithm is necessarily too weak","Protection at rest and in transit does not automatically protect data in use","The disk's recovery key must have been stolen before the memory read"],"explanations":["TLS protects transport rather than every endpoint memory operation.","The data had already been decrypted; the attack need not break the algorithm.","Once decrypted for processing, plaintext needs separate memory and execution protections.","Reading already decrypted process memory does not require stealing the recovery key."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-047","objective":"3.3","concept":"Residency versus access location","prompt":"A contract requires both primary customer records and their recovery copies to remain in Country X. The main database is compliant, but snapshots replicate to Country Y. Which change is required?","options":["Keep the database's primary writer in Country X but leave replicas elsewhere","Encrypt cross-border snapshots with keys retained only in Country X","Require vendor administrators to connect through a Country X jump host","Restrict backup replication and storage to permitted locations"],"explanations":["The stated requirement also covers recovery copies, not only the primary writer.","An explicit rule covering storage location still applies to encrypted copies.","Access routing does not relocate snapshots stored in Country Y.","Recovery copies are within the stated location requirement."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-048","objective":"3.4","concept":"RPO calculation","prompt":"An outage occurs at 14:20. The most recent usable backup completed at 13:45. The business permits at most 20 minutes of data loss. Which assessment is correct?","options":["The potential 35-minute data-loss window exceeds the RPO by 15 minutes","The RPO is met because restoration has not yet consumed 20 minutes","The potential 35-minute gap exceeds the RTO by 15 minutes","The potential data-loss window is 15 minutes and stays within the RPO"],"explanations":["Recovery point objective, or RPO, concerns recoverable data age: 14:20 minus 13:45 is 35 minutes.","RPO measures data loss, not time spent restoring.","That confuses data age with downtime; the stated target is for data loss.","The time since the usable backup is 35 minutes; 15 is the amount over the limit."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-049","objective":"3.4","concept":"Replication versus backup","prompt":"A database replica instantly copies both valid transactions and an accidental mass deletion. Which additional capability BEST addresses this failure mode?","options":["A second synchronous replica in another building","Versioned point-in-time recovery with protected historical copies","A faster replication interval to minimize lag","Automatic failover to the replica after the deletion is applied"],"explanations":["Another current replica can apply the same deletion.","Historical states can recover data that a current replica faithfully deleted.","Faster copying propagates the destructive operation rather than preserving an earlier version.","Failover changes the active copy, but both now contain the deletion."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-050","objective":"3.4","concept":"Common-mode failure","prompt":"Two firewalls run in a failover pair on separate power supplies, but both connect through one upstream switch. Which improvement MOST directly addresses the remaining single point of failure?","options":["Add a second power supply to the shared switch while leaving one switching chassis","Replace the standby firewall with a higher-throughput model","Provide redundant upstream switching and independent connections","Increase firewall state synchronization frequency"],"explanations":["That may improve power resilience but leaves the common chassis failure.","Both peers still depend on the shared switch.","Either firewall still depends on the single shared switch.","Session-state readiness does not remove upstream dependency."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-051","objective":"3.4","concept":"Recovery exercise evidence","prompt":"A team successfully discusses a disaster plan around a table. Management now wants evidence that backup media can actually restore the application within its target time. What should happen NEXT?","options":["Verify backup file checksums without starting the recovered application","Run another tabletop focused on the written restore sequence","Compare scheduled backup completion times with the recovery time objective","Perform a measured restoration test in an isolated environment"],"explanations":["Integrity checking helps but does not prove a functioning application restore within target time.","Discussion does not establish that the data restores or meets the time target.","Backup creation time is not measured restoration time.","Executing restoration tests both technical recoverability and elapsed recovery time."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-052","objective":"3.4","concept":"Power continuity design","prompt":"A generator starts 45 seconds after utility failure, but critical controllers reboot after two seconds without power. Which addition BEST closes the continuity gap?","options":["A UPS sized to bridge startup and transfer time","Increase the generator's runtime fuel supply","Use two generators that both begin supplying power after 45 seconds","Add surge suppression without stored-energy support"],"explanations":["An uninterruptible power supply, or UPS, supplies immediate short-term power before the generator takes over.","More runtime does not cover the first 45 seconds.","Redundant delayed supply still leaves the immediate gap.","Surge controls handle spikes, not the period without power."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-053","objective":"4.1","concept":"Secure baseline verification","prompt":"A new server matches the approved image, but an administrator later enables an unnecessary remote service. Which process BEST detects this deviation consistently?","options":["Reimage every server annually without intermediate configuration assessment","Compare live configurations against the approved baseline","Review only successful operating-system patch installations","Compare the server hostname with its deployment ticket"],"explanations":["Changes between rebuilds remain unassessed.","Ongoing configuration checks detect drift after image deployment.","Patch compliance does not establish that unnecessary services remain disabled.","Identity consistency does not validate current configuration."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-054","objective":"4.1","concept":"Mobile ownership boundaries","prompt":"A personally owned phone contains a managed work container and private photos. The employee leaves. Which action BEST removes business data while respecting ownership?","options":["Issue an unconditional full-device wipe using the work management channel","Revoke cloud access but retain cached work-container data on the phone","Selectively wipe the managed work container and revoke business access","Remove the device's Wi-Fi certificate but leave its managed applications and files"],"explanations":["That unnecessarily targets private content despite a separable work container.","Account revocation alone does not remove the local business copies.","A selective wipe targets organizational data without erasing unrelated personal content.","Certificate revocation does not erase the existing work data."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-055","objective":"4.1","concept":"Patch integrity before installation","prompt":"An urgent patch is downloaded from a mirror. Its signature fails validation even though its filename and version match the advisory. What should the administrator do FIRST?","options":["Compare the version string with the advisory and waive the failed check","Install first on a pilot host and accept it if no crashes occur","Approve the mirror based only on its valid HTTPS certificate","Obtain and validate a trusted copy before deployment"],"explanations":["A version string is not cryptographic evidence of publisher authenticity.","A functional pilot cannot establish the authenticity of a package with failed validation.","Transport identity does not fix the patch's failed signature check.","Urgency does not make a failed integrity or authenticity check acceptable."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-056","objective":"4.2","concept":"Asset reconciliation","prompt":"A discovery scan finds an active database host absent from the asset register. A procurement record shows the hardware was purchased last year. What is the BEST next asset-management action?","options":["Identify its owner, purpose, data classification, and lifecycle status","Register it under procurement as owner without validating how it is used","Quarantine it as malicious solely because the inventory entry is absent","Create an inventory entry from its IP address alone and close the discrepancy"],"explanations":["Discovery must be reconciled into accountable inventory rather than assuming purchase equals authorization.","The purchasing department may not be operationally accountable.","An unexplained asset needs assessment, but absence alone does not prove maliciousness.","Address-only recording omits ownership, purpose, and data-handling context."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-057","objective":"4.2","concept":"Disposal evidence","prompt":"A contractor claims to have destroyed drives containing regulated data. The internal team must close the disposal records. Which evidence BEST supports that closure?","options":["A signed generic letter stating that the contractor follows secure practices","A destruction record linked to the specific drive serial numbers and custody trail","The transfer manifest without any evidence of final destruction","A record showing that filesystem format commands ran successfully"],"explanations":["A generic assurance does not identify these drives or their disposition.","Asset-specific evidence connects the promised destruction to the actual media transferred.","A handoff record establishes movement, not the completed outcome.","Formatting evidence does not establish the promised physical destruction."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-058","objective":"4.3","concept":"Vulnerability prioritization context","prompt":"One critical flaw affects an isolated test server with synthetic data. A slightly lower-rated flaw is actively exploited on an internet-facing authentication service. Which should normally receive the highest immediate priority?","options":["The isolated flaw because testing its patch would be less disruptive","The isolated flaw because its base severity is higher, without applying environmental context","The actively exploited flaw on the exposed authentication service","Both at identical priority because only numeric scanner scores are permitted inputs"],"explanations":["Ease of change is relevant to scheduling but does not outweigh the stated immediate exploitation risk.","A base score alone omits the exposure and active exploitation of the authentication service.","Exploit activity, reachability, and business impact outweigh severity score alone.","Risk prioritization should incorporate business context and exploitation evidence."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-059","objective":"4.3","concept":"Scanner false positive validation","prompt":"A scanner reports an old vulnerable web-server version from its banner. The vendor says the installed package backports the fix without changing that banner. What is the BEST validation step?","options":["Disable version reporting and treat the vulnerability as remediated","Close the finding immediately because the vendor mentioned backporting","Classify the server as exploitable solely from the banner","Compare installed package and patch evidence with the vendor's advisory"],"explanations":["Hiding a version does not establish whether the flaw is fixed.","The specific installed package still needs verification.","A banner can remain unchanged after the relevant fix.","Backported fixes require package-level evidence rather than relying solely on banner text."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-060","objective":"4.3","concept":"Remediation validation","prompt":"A team deploys a patch and closes its change ticket. What additional action BEST establishes that the reported vulnerability is resolved on the affected hosts?","options":["Run a targeted validation scan and investigate any remaining detections","Confirm that deployment software downloaded the patch package","Ask the administrator to attest that every ticket is closed","Run the scan without needed credentials and treat skipped checks as passes"],"explanations":["Remediation verification checks the resulting state rather than merely the deployment action.","Download success does not establish installation and remediation on affected hosts.","Ticket status does not independently verify the actual resulting state.","Missing coverage cannot validate local patch state."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-061","objective":"4.4","concept":"SIEM versus response automation","prompt":"A SIEM correlates suspicious login events correctly, but analysts manually enrich every alert and disable accounts. Which addition MOST directly automates that repeatable response workflow?","options":["Add a SIEM correlation rule that only creates another alert","SOAR with controlled playbooks and approval gates","Expand log retention and create a daily analyst report","Add a vulnerability scanner to the same log dashboard"],"explanations":["Another alert does not orchestrate the enrichment and account action.","Security orchestration, automation, and response coordinates enrichment and actions across tools.","That preserves evidence but leaves the manual response steps intact.","Scanning finds weaknesses rather than coordinating this response workflow."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-062","objective":"4.4","concept":"Detection tuning safeguards","prompt":"A noisy alert repeatedly triggers during an approved backup job. Which tuning change BEST reduces false positives without suppressing unrelated attacks?","options":["Ignore all activity using the same administrative account","Disable the alert for every host that has backup software","Scope the exception to the verified job identity, hosts, and schedule","Raise the threshold beyond all observed production activity"],"explanations":["A compromised account could perform unrelated malicious actions.","That suppresses suspicious behavior outside the known benign job.","A narrow contextual exception preserves detection outside the approved behavior.","An overly broad threshold may hide real attacks along with noise."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-063","objective":"4.4","concept":"Log pipeline failure","prompt":"A dashboard shows zero authentication failures overnight. The collector's last received timestamp is yesterday, while the identity server has new local failures. What should be investigated FIRST?","options":["Disable local identity logging to avoid inconsistent counts","Rebaseline the alert threshold because fewer failures appear centrally","Close the password-attack investigation based on the empty dashboard","A forwarding or ingestion failure between source and collector"],"explanations":["That removes evidence instead of repairing ingestion.","Threshold changes should not conceal a broken evidence pipeline.","The source has fresh failures and the collector is stale.","The source has events that the collector has not received, so absence on the dashboard is not reassurance."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-064","objective":"4.5","concept":"Firewall state and return traffic","prompt":"A stateful firewall allows clients to initiate HTTPS to a vendor. Return packets are denied after a failover because connection state was not synchronized. What is the BEST correction?","options":["Synchronize session state between failover peers","Allow all inbound traffic to the clients' ephemeral-port range","Increase the clients' TCP timeout without sharing firewall connection state","Add only an outbound HTTPS rule to the standby peer"],"explanations":["Established return traffic depends on connection tracking surviving the device transition.","That bypasses the missing-state issue through an excessively broad rule.","Waiting longer does not create the missing state on the new active device.","The request rule does not restore knowledge of connections already established before failover."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-065","objective":"4.5","concept":"Email authentication alignment","prompt":"A message has From: billing@alpha.example. SPF passes for bounce.vendor.example; DKIM passes with d=alpha.example. Assuming valid checks and ordinary DMARC alignment rules, what is the result?","options":["DMARC fails because both authentication mechanisms must align","DMARC can pass because the valid DKIM signature aligns with the From domain","DMARC passes because any SPF pass is sufficient even for an unrelated envelope domain","DMARC fails because a different envelope domain overrides an aligned DKIM pass"],"explanations":["An aligned pass from either SPF or DKIM can satisfy DMARC.","Domain-based Message Authentication, Reporting, and Conformance needs an aligned pass from SPF or DKIM.","The SPF result is unaligned; the aligned DKIM pass is what satisfies DMARC here.","Unaligned SPF does not cancel a valid aligned DKIM result."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-066","objective":"4.5","concept":"DNS filtering versus payload inspection","prompt":"A company blocks domains associated with malware, but an infected host connects directly to an IP address without DNS resolution. Which limitation is demonstrated?","options":["The domain's record must have expired at the filtering resolver","The DNS policy must be bypassed through an unauthorized recursive resolver","DNS filtering alone does not inspect connections that bypass DNS","Encrypted DNS is necessarily hiding the malicious lookup"],"explanations":["The described connection needs no DNS answer.","A direct IP connection can bypass resolution entirely without another resolver.","Other network or endpoint controls are needed for direct-address traffic.","No lookup is described, so encrypted DNS is not required to explain the gap."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-067","objective":"4.5","concept":"DLP contextual controls","prompt":"Employees may upload public brochures to a partner portal, but not customer records. Both use the same HTTPS destination. Which control BEST enforces this distinction?","options":["Limit upload size so that all large files are blocked","Allow only the partner's domain name and block other destinations","Require client certificates but permit every authenticated upload","Content-aware DLP at a point with authorized access to the upload data"],"explanations":["Size alone cannot reliably distinguish public brochures from customer records.","Both permitted and forbidden uploads use the same approved destination.","Strong client identity does not classify the uploaded data.","Data loss prevention must distinguish the content, not merely the shared destination."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-068","objective":"4.6","concept":"Federation versus provisioning","prompt":"A federated application trusts the identity provider, but a newly assigned employee receives 'no local account' after successful authentication. What additional process is missing?","options":["Provisioning the employee's application account and entitlements","Assign a different MFA method at the identity provider","Rotate the identity provider's signing key and reissue all assertions","Add the application URL to the employee's bookmarks"],"explanations":["Federated authentication does not guarantee that the application has created a usable local identity.","The authentication has already succeeded; the application lacks an account.","There is no stated assertion-validation failure.","A shortcut does not create an account or authorize application access."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-069","objective":"4.6","concept":"Phishing-resistant authentication","prompt":"An attacker relays a user's password and one-time code through a look-alike website in real time. Which authentication method BEST addresses this specific relay risk?","options":["Use a shorter-lived TOTP generated by an authenticator app","Origin-bound FIDO2 authentication","Send the one-time code over a separate SMS channel","Require two separate memorized secrets on the login form"],"explanations":["Time-based one-time passwords can still be relayed while valid.","FIDO2 binds authentication to the legitimate site, making a look-alike origin unable to reuse the assertion.","An attacker can ask the victim to enter and relay that code.","Both secrets can be captured and relayed through the imitation site."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-070","objective":"4.6","concept":"Just-in-time privileged access","prompt":"An engineer needs elevated database rights for a 30-minute repair. Which design BEST limits both standing privilege and accountability gaps?","options":["Check out a shared DBA password without session attribution","Grant a permanent privileged role and review membership quarterly","Grant individually approved, time-limited elevation with session logging","Grant a time-limited domain-admin role instead of database-scoped rights"],"explanations":["A shared identity weakens accountability and does not inherently limit privilege duration.","Standing authority remains between reviews.","Just-in-time access narrows exposure and links actions to the specific person.","Time limitation helps but the role unnecessarily exceeds the repair's scope."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-071","objective":"4.6","concept":"Attribute-based authorization","prompt":"Two analysts share a job role, but access must also depend on project membership, device compliance, and request location. Which model BEST expresses the complete rule?","options":["Authorize by network location alone and assume all internal devices are compliant","Assign both analysts the same role and rely only on that role's permissions","Allow each analyst to set discretionary permissions on project data","Attribute-based access control"],"explanations":["Location alone fails the other explicitly required conditions.","The identical role cannot express the differentiating context by itself.","User discretion does not necessarily enforce device and location restrictions.","ABAC evaluates multiple user, resource, and environmental attributes together."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-072","objective":"4.7","concept":"Automation failure containment","prompt":"A response script disables every account returned by a query. A malformed query once returned the entire directory. Which safeguard MOST directly limits recurrence's impact?","options":["Validate result scope and require approval above a small action threshold","Require a human to approve only the initial script deployment","Use automatic retries whenever more than ten accounts are returned","Record disabled accounts after execution without a pre-action scope check"],"explanations":["Scope checks and circuit breakers prevent a bad query from causing mass account actions.","A later bad result set can still trigger mass actions.","Retries do not constrain an erroneous bulk result.","Logs aid recovery but do not limit the initial blast radius."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-073","objective":"4.7","concept":"Secret handling in automation","prompt":"A deployment script stores a production API key in a repository that many developers can read. Which replacement BEST reduces exposure while preserving unattended execution?","options":["Encrypt the key in the repository and commit its decryption password beside it","Retrieve a narrowly scoped secret at runtime from a controlled secrets service","Move the key to a repository configuration file with the same reader permissions","Suppress the key in normal output but keep it hard-coded in source"],"explanations":["Readers can recover the secret using the co-located decryption material.","Centralized secret access supports restricted permissions, auditing, and rotation without hard-coding.","The same people still receive the production secret.","Output masking does not protect the source copy."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-074","objective":"4.8","concept":"Volatile evidence priority","prompt":"A contained server is still running. Investigators need evidence of a memory-only payload and its current connections. Which collection should normally precede powering it down?","options":["Disconnect power and then acquire memory from the powered-off system","Take only a filesystem image before removing power","Acquire volatile memory and live connection information using approved procedures","Export only central event logs and immediately rebuild the server"],"explanations":["Ordinary RAM acquisition after power loss loses the relevant volatile state.","Disk acquisition may omit the memory-only payload and current connections.","Power loss destroys volatile evidence central to the investigation.","Central logs may not contain the current memory evidence sought."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-075","objective":"4.8","concept":"Chain of custody versus integrity","prompt":"A disk image's hash matches its acquisition hash, but there is no record of who held the evidence for three days. Which issue remains unresolved?","options":["The image must be reacquired solely because hashes are irreversible","The image's technical integrity has necessarily failed","The acquisition method must have modified every file","Chain-of-custody documentation"],"explanations":["Hash irreversibility is normal and unrelated to the documentation problem.","Matching hashes support integrity, while handling history is a separate gap.","The missing custody record does not establish that modification occurred.","Matching hashes support integrity, but do not document possession and handling."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-076","objective":"4.8","concept":"Containment timing","prompt":"Confirmed ransomware is actively encrypting a file share from one workstation. An approved playbook authorizes endpoint isolation. What should the responder do NEXT?","options":["Isolate the workstation's network access while preserving available evidence","Wait to isolate until a full disk image has completed","Reset the user's password but keep existing connections active","Restore the share immediately before addressing the active source"],"explanations":["Immediate authorized containment limits ongoing harm; evidence collection should accompany response as feasible.","Active ongoing encryption can cause further harm during a lengthy acquisition.","Existing sessions and running malware can continue accessing the share.","The connected source can damage restored data again."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-077","objective":"4.8","concept":"Recovery versus eradication","prompt":"Malicious accounts and persistence have been removed, the exploited weakness is fixed, and integrity checks pass. Which action belongs MOST directly to recovery?","options":["Delete an identified malicious scheduled task from the host","Restore approved services in stages and monitor for recurrence","Determine the original exploit through forensic analysis","Revise the organization's long-term response policy"],"explanations":["Removing persistence is eradication, which precedes safe restoration.","Recovery returns clean services to operation with continued validation.","That is investigation rather than the specific return-to-service activity.","That supports lessons learned and preparation rather than immediate recovery."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-078","objective":"4.9","concept":"Authentication log interpretation","prompt":"An identity log shows: 09:01 password accepted; 09:01 MFA challenge denied; 09:02 session not issued. What is the MOST accurate conclusion?","options":["The event establishes that every second factor on the account is uncompromised","A complete authenticated session was established because the password was accepted","The password may be compromised, but this attempt did not complete authentication","The event can be closed with no password-risk investigation"],"explanations":["One denied challenge does not establish the security of every factor or other session.","The record explicitly states that no session was issued.","The accepted first factor is concerning; the denied second factor prevented session issuance in this record.","An accepted first factor can indicate a valid password in the wrong hands."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-079","objective":"4.9","concept":"Web log sequence inference","prompt":"A source requests /admin.old, /backup.zip, /.git/config, and /db.sql within two seconds; all return 404. Which conclusion is BEST supported?","options":["The sequence is necessarily a successful authenticated administrator session","The sequence proves that a backup archive was exfiltrated","The sequence proves successful SQL query injection","The source is probing for exposed resources; successful access is not shown"],"explanations":["Resource probing and 404 responses do not establish authentication or authorized access.","The shown 404 responses do not establish a successful download.","Requesting a .sql filename is not evidence of query manipulation.","The path pattern indicates enumeration, while 404 responses do not show retrieval of the requested resources."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-080","objective":"4.9","concept":"Evidence source granularity","prompt":"An analyst needs to know which executable created an outbound connection from a laptop. Firewall logs show only addresses and ports. Which source BEST fills the gap?","options":["Endpoint process and network telemetry","Network flow records for the same laptop and time window","Packet captures from a switch mirror without endpoint process metadata","DNS query logs for the destination's hostname"],"explanations":["Endpoint records can associate a socket with its creating process.","Flows usually provide connection metadata rather than the originating executable.","Packets can reveal traffic but normally do not identify the local process that created it.","A query can help correlate a destination but does not reliably assign the socket to an executable."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-081","objective":"5.1","concept":"Policy exception governance","prompt":"A business unit cannot meet a security standard for 60 days. Which response BEST maintains governance while allowing an assessed exception?","options":["Let the project manager accept the deviation without checking delegated authority","Record the risk, compensating measures, accountable approval, and expiration date","Mark the current deployment compliant because compensating controls are planned","Issue an exception with no end date because the replacement is scheduled"],"explanations":["The correct approving authority must be established for the risk.","A bounded, authorized exception keeps the departure visible and subject to review.","Planned measures do not demonstrate present implementation or approved acceptance.","An expiration and reassessment point keep a temporary deviation from silently becoming permanent."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-082","objective":"5.1","concept":"Data role accountability","prompt":"A vendor originally processes survey responses only under its customer's instructions. It now proposes using identifiable responses to develop an unrelated product of its own. What governance issue needs review FIRST?","options":["The customer ceases to have any responsibility as soon as data is transferred","The original processor agreement automatically authorizes every future analytic use","The vendor is proposing its own processing purpose beyond the existing instructions","Removing names alone necessarily makes all identifiable response combinations unrestricted"],"explanations":["Outsourcing processing does not automatically eliminate the customer's obligations.","A new independent purpose is not established by the original limited instructions.","A processor cannot assume that the original instructed purpose authorizes an independent new use; role and agreement obligations need reassessment.","Removing one identifier does not guarantee de-identification or authorize a new purpose."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-083","objective":"5.1","concept":"Separation of duties in approvals","prompt":"A single administrator requests, approves, and implements changes to audit-log retention. Which governance change BEST reduces the risk of concealed misuse?","options":["Require changes to reference a ticket that the implementer can also approve","Require the same administrator to review their own changes each month","Move the retention console behind MFA while keeping unilateral approval","Require independent approval for retention changes and retain an audit trail"],"explanations":["A self-approved ticket preserves the same conflict.","Self-review does not create independent authorization.","MFA improves identity assurance but not separation of conflicting duties.","Separating approval from implementation reduces unilateral control over evidence retention."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-084","objective":"5.1","concept":"Document hierarchy application","prompt":"A corporate standard requires encrypted remote administration. Teams need the exact approved command sequence for configuring a particular router model. Which document should supply that sequence?","options":["A procedure aligned with the standard","A policy stating that all administrative traffic must be encrypted","A guideline suggesting optional router configuration alternatives","A standard naming approved encryption protocols and minimum strengths"],"explanations":["A procedure gives concrete implementation steps supporting a mandatory standard.","That is governing direction rather than the requested command-level steps.","Optional guidance does not supply the approved mandatory execution sequence.","The standard sets requirements but usually does not provide model-specific commands."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-085","objective":"5.2","concept":"Annualized loss calculation","prompt":"A service asset is valued at $180,000. One incident would affect 35% of that value, with an expected frequency of 0.4 events per year. The annual loss tolerance is $20,000. Which assessment is correct?","options":["Expected annual loss is $63,000, exceeding tolerance by $43,000","Expected annual loss is $25,200, exceeding tolerance by $5,200","Expected annual loss is $72,000, exceeding tolerance by $52,000","Expected annual loss is $15,750, below tolerance by $4,250"],"explanations":["That treats single loss expectancy as annual loss without applying frequency.","SLE is $63,000; multiplying by 0.4 gives ALE $25,200, which is $5,200 above the limit.","That applies frequency to full asset value while omitting the exposure factor.","That calculation does not correctly apply the stated 0.4 annual occurrence rate."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-086","objective":"5.2","concept":"Risk treatment economics","prompt":"A safeguard costs $18,000 per year and reduces estimated annual loss from $50,000 to $20,000. Ignoring nonfinancial effects, what is its estimated annual net benefit?","options":["$32,000","$30,000","$12,000","$48,000"],"explanations":["Subtracting cost from the old loss ignores the remaining $20,000 exposure.","That is gross loss reduction before the safeguard's cost.","The $30,000 reduction in expected loss minus $18,000 annual cost leaves $12,000.","Adding cost to risk reduction treats an expense as a benefit."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-087","objective":"5.2","concept":"Risk appetite versus tolerance","prompt":"A board broadly accepts moderate innovation risk, but an approved service metric permits no more than two hours of outage per quarter. What BEST describes the two-hour limit?","options":["Maximum tolerable downtime for one continuous outage","Risk appetite for the organization as a whole","Recovery time objective for each individual outage","Risk tolerance for a measurable service outcome"],"explanations":["The scenario states a quarterly total, not a single disruption's maximum duration.","Appetite is the broader willingness to take risk rather than this specific measurable boundary.","A quarterly accumulated downtime limit is not necessarily the allowed recovery time for a single incident.","Tolerance turns broad appetite into a more specific acceptable variation or boundary."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-088","objective":"5.2","concept":"Risk transfer limitations","prompt":"A covered incident causes $150,000 in loss. Insurance pays eligible loss after a $20,000 deductible, capped at $100,000 of insurer payment. Ignoring other costs, how much loss remains with the company?","options":["$50,000","$20,000","$70,000","$130,000"],"explanations":["Eligible loss after the deductible is $130,000; the insurer pays its $100,000 cap, leaving $50,000.","The deductible alone ignores the loss above the insurer's payout cap.","That subtracts the deductible twice when applying the stated payout cap.","That is eligible loss before the cap, not the company's remaining loss."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-089","objective":"5.2","concept":"Risk register ownership","prompt":"A risk register lists a serious supplier outage risk, a likelihood score, and a mitigation deadline, but nobody is accountable for following through. What is the MOST important missing field?","options":["An additional residual-risk score without a named accountable party","A designated risk owner","A list of every employee affected by an outage","A statement that the supplier accepts its own internal business risks"],"explanations":["Another score still leaves nobody responsible for follow-through.","An owner is accountable for tracking the risk and ensuring appropriate treatment decisions.","Stakeholders are useful, but they do not replace a designated risk owner.","The customer still needs an owner for its own dependency risk."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-090","objective":"5.3","concept":"Contract scope distinctions","prompt":"A provider meets its uptime target but disputes whether weekend incident-response support was included in the purchased engagement. Which document BEST resolves the contracted work scope?","options":["Master services agreement defining general legal terms but no engagement details","Service-level agreement specifying the already satisfied uptime metric","Statement of work","Nondisclosure agreement covering incident information"],"explanations":["The specific scope belongs in the engagement's statement of work.","An uptime SLA alone does not establish which response-service hours were purchased.","An SOW defines the specific deliverables, services, and work boundaries.","Confidentiality terms do not settle the purchased work scope."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-091","objective":"5.3","concept":"Supplier evidence quality","prompt":"A critical supplier sends a one-page statement saying it has 'strong security.' Procurement needs evidence that relevant controls operated during the last year. What is the BEST next request?","options":["A questionnaire consisting solely of the supplier's unsupported yes/no answers","A current audit report for an unrelated product offered by the supplier","A point-in-time control-design statement with no operating-period testing","An independent assurance report covering the relevant service and period"],"explanations":["Self-assertions are weaker than appropriately scoped independent operating evidence.","Assurance must cover the service being evaluated.","Design evidence alone does not establish operation during the requested year.","Scope and reporting period matter when evaluating operating effectiveness."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-092","objective":"5.3","concept":"Exit planning and data control","prompt":"A SaaS contract is ending. The company needs its records in usable form and assurance that the vendor's remaining copies are handled as agreed. What should the exit plan explicitly address?","options":["Data export, retention obligations, and verifiable deletion or return","Account deactivation without documenting export or remaining vendor copies","Contract termination notice alone, without data-handling milestones","An export in an undocumented proprietary format with no deletion evidence"],"explanations":["Exit planning must cover usable recovery and the agreed disposition of retained copies.","Closing logins does not recover records or control retained copies.","Notice does not establish the actual disposition of data.","An unusable export and unaddressed residual copies fail both stated needs."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-093","objective":"5.4","concept":"Compliance versus security","prompt":"A system passed last year's audit but now has an exposed unsupported component outside that audit's scope. Which conclusion is MOST accurate?","options":["The audit's overall pass applies indefinitely to every connected component","Prior compliance evidence does not establish current security for that component","An out-of-scope component can be assumed safe until the next annual audit","Only a repeat of the identical audit can authorize any risk-reducing action"],"explanations":["Audit conclusions are limited by scope and time.","Scope and time limit what an audit conclusion can support.","Exposure exists regardless of the audit calendar.","Operational risk management can address newly identified conditions now."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-094","objective":"5.4","concept":"Legal hold and retention","prompt":"A routine retention rule would delete records tomorrow, but authorized counsel has issued a hold covering those records. What should the organization do?","options":["Apply ordinary deletion to copies not personally reviewed by counsel","Retain file hashes while deleting the covered records on schedule","Suspend applicable deletion and preserve the covered records under the hold","Extend retention only for newly created records after the hold date"],"explanations":["The hold's defined scope governs preservation, not individual review of every item.","Hashes do not preserve the records' contents.","A legal hold pauses ordinary disposal for the specified material.","The hold can cover existing records; excluding them would not meet it."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-095","objective":"5.5","concept":"Assessment scope and authorization","prompt":"A permitted test demonstrates that payroll records can be read. The rules require minimizing data collection and prohibit retaining employee records. What should the tester do NEXT?","options":["Delete all test notes so no finding can be associated with payroll data","Download the full database to prove the maximum possible impact","Send sample employee records to all department heads immediately","Preserve minimal redacted proof and report through the agreed channel"],"explanations":["Minimization does not require discarding permissible redacted evidence of the weakness.","The demonstrated read already supports impact; retaining employee records violates the engagement.","Broad distribution exceeds the agreed evidence and communication restrictions.","Evidence should demonstrate the finding while respecting collection and retention restrictions."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-096","objective":"5.5","concept":"Independent assurance","prompt":"An administrator designs a control, operates it, and then signs the only effectiveness assessment. What improvement BEST strengthens assurance?","options":["Have a suitably independent assessor evaluate the control evidence","Have the control operator add a self-certification checklist to the same report","Use only the absence of detected incidents as proof of effectiveness","Let the implementer select only successful samples and exclude failures"],"explanations":["Independence reduces the conflict involved in evaluating one's own work.","A checklist can help documentation but does not add independence.","Undetected incidents and untested control failures can exist.","Biased sampling weakens rather than strengthens assurance."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-097","objective":"5.5","concept":"Known versus unknown testing","prompt":"After a red team succeeds, defenders want to learn which telemetry detected each attack step and refine their rules with the attackers. Which exercise format BEST supports that goal?","options":["An additional blind red-team exercise with no collaboration until the end","A collaborative purple-team exercise","A compliance self-assessment limited to written procedures","A vulnerability scan that reports only missing patch levels"],"explanations":["That measures independent detection but does not provide the requested step-by-step collaboration.","Attack and defense teams jointly validate visibility and improve detection against demonstrated techniques.","Document review does not validate telemetry against the actual attack steps.","Patch detection does not evaluate defensive visibility across the attack sequence."],"correct":1,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-098","objective":"5.6","concept":"Awareness measurement","prompt":"After training, phishing simulation click rates fall but reporting rates also collapse. Which interpretation is MOST appropriate?","options":["Rank teams only by how few incidents they report","Declare success solely from the reduced click count","Click reduction alone is insufficient; investigate whether staff can recognize and report threats","Replace reporting metrics entirely with training attendance"],"explanations":["That can reward underreporting rather than safer behavior.","The decline in reporting may weaken detection and needs investigation.","Reporting behavior matters, and a single improving metric does not establish effective awareness.","Attendance does not establish recognition and reporting performance."],"correct":2,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-099","objective":"5.6","concept":"Role-specific training","prompt":"Developers repeatedly place secrets in source repositories, while general phishing training scores are high. Which intervention BEST addresses the observed gap?","options":["Test developers only on acronym definitions for authentication protocols","Add more generic phishing simulations using the same email themes","Require only a yearly acknowledgment of the broad security policy","Developer-focused practice on secret handling and secure build workflows"],"explanations":["Definition recall does not establish secure repository and build behavior.","That does not directly practice the development behavior causing exposure.","Acknowledgment alone does not teach a secure secret-handling workflow.","Training should target the role and behavior producing the actual exposure."],"correct":3,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH1-100","objective":"5.6","concept":"Reporting culture","prompt":"Employees delay reporting suspicious clicks because they fear automatic disciplinary action. Which change BEST improves early detection?","options":["Provide a simple, supportive reporting path and reinforce prompt reporting","Require a manager to validate technical evidence before any report reaches security","Automatically discipline every reporter who clicked a simulation link","Accept only anonymous reports with no way to request follow-up details"],"explanations":["Lowering barriers encourages reports while investigation can still address actual misconduct.","That adds a barrier and can delay investigation.","That reinforces concealment incentives.","Anonymous options can help, but making all reports uncontactable can impede investigation."],"correct":0,"examId":"challenge-1","revision":"challenge-v13","type":"mcq","provenance":"Original practice"}]},{"id":"challenge-2","name":"Challenge Exam 2","questions":[{"id":"CH2-001","objective":"1.1","concept":"Corrective versus preventive role","prompt":"An automated control detects unauthorized firewall-rule changes and restores the approved ruleset. The assessor is classifying the restoration action, not the alert. Which functional type BEST fits?","options":["Preventive","Detective","Corrective","Directive"],"explanations":["The rule was already changed, so restoration did not prevent that change.","Detection identifies the deviation; the question isolates the later restoration action.","Restoration repairs the unauthorized state after the deviation occurs.","The action changes the configuration rather than instructing a person to follow policy."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-002","objective":"1.1","concept":"Deterrence versus detection design","prompt":"A loading dock installs conspicuous warning signs describing recorded surveillance. A separate system records activity. When evaluating only the signs' intended effect on a potential trespasser, which type BEST applies?","options":["Compensating","Detective","Corrective","Deterrent"],"explanations":["No unavailable primary requirement or substitute safeguard is specified.","A sign cannot itself capture or report a trespass event.","The signs do not restore the site after an incident.","The signs aim to discourage an attempt; the actual recording provides separate detection evidence."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-003","objective":"1.2","concept":"Authorization boundary in AAA","prompt":"A certificate-authenticated automation account successfully connects to a service. It can read reports but receives 'operation not permitted' when attempting deletion. Which function is making the distinction?","options":["Authorization","Authentication","Accounting","Identity proofing"],"explanations":["The authenticated identity is being checked for permission to perform a particular action.","Certificate authentication has already established the identity for this connection.","Recording actions supports accountability but does not itself grant or deny them.","Initial identity verification is distinct from this runtime operation-permission check."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-004","objective":"1.2","concept":"Nonrepudiation prerequisites","prompt":"A purchasing department signs approvals using one private key shared by six staff members. Signatures validate correctly. What claim is LEAST supported by those signatures alone?","options":["The signed content has not changed since the signature was created","A specific named employee personally approved each purchase","The corresponding private key was used to create the signature","Anyone without the private key should be unable to forge a valid signature"],"explanations":["A valid digital signature can still support integrity despite shared custody.","A shared private key cannot uniquely attribute signatures to one of its holders.","Successful verification links the signature to that key, not to a unique human holder.","Key sharing among authorized holders does not by itself enable outsiders to forge signatures."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-005","objective":"1.2","concept":"Physical layered controls","prompt":"A facility has badge-controlled doors, but authorized staff routinely hold them open for unbadged people. Logs show only the first badge holder. Which addition BEST addresses this precise entry-accountability gap?","options":["Require a PIN in addition to the first entrant's badge at the same held-open door","Apply anti-passback checks only when someone presents a badge","An access-control vestibule requiring individual authentication per entry","Shorten badge validity and review the same first-person access records daily"],"explanations":["The stronger first-person authentication does not ensure individual passage.","A follower who never presents a badge can bypass that event-based check.","Individual passage controls address the shared-door entry that ordinary badge logs miss.","Neither step records or controls the unbadged follower's passage."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-006","objective":"1.3","concept":"Emergency change governance","prompt":"An actively exploited flaw requires a patch before the next routine change-board meeting. The organization has a documented emergency process. What is the BEST action?","options":["Wait for the routine change board while leaving the actively exploited service exposed","Use the normal change ticket but skip approval because the patch is vendor signed","Authorize an emergency deployment and omit the rollback assessment to save time","Use emergency authorization, assess impact, prepare recovery, and document follow-up review"],"explanations":["The established emergency process provides an authorized faster route.","Code authenticity does not establish authority to deploy the emergency change.","The emergency route still needs proportionate impact and recovery planning.","Urgency changes the approved route; it does not eliminate controls and accountability."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-007","objective":"1.3","concept":"Post-change evidence","prompt":"A segmented network redesign is deployed successfully and validated. The diagrams still show the old trust boundaries. Which remaining task MOST directly prevents future security decisions from using a false architecture model?","options":["Update and version the authoritative network documentation","Extend the completed change's maintenance window","Reapprove the unchanged diagram under the new change number","Archive a second copy of the old diagram without publishing the new design"],"explanations":["Accurate controlled diagrams preserve the implemented boundary model for future decisions.","More time does not correct the obsolete documentation.","Approval of an inaccurate model leaves future decisions based on false boundaries.","Historical preservation alone does not supply an accurate current architecture."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-008","objective":"1.4","concept":"Certificate signing request contents","prompt":"A service owner submits a CSR to a certificate authority. Which material should remain under the owner's protection rather than be included in the request?","options":["The public key that the certificate will bind to the identity","The private key corresponding to the requested public key","The requested service names or identity information","A signature proving possession of the corresponding private key"],"explanations":["The authority needs that public key to issue the certificate.","A certificate signing request, or CSR, conveys public-key and identity information; the private key stays secret.","These identify the subject for certificate validation and issuance.","The CSR is normally signed without disclosing the private key itself."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-009","objective":"1.4","concept":"Wildcard certificate boundary","prompt":"A certificate contains only *.ops.example. Which hostname does that wildcard ordinarily cover?","options":["east.api.ops.example","ops.example","api.ops.example","api.example"],"explanations":["The wildcard does not ordinarily span multiple hostname labels.","The parent name needs its own certificate name entry.","A wildcard in this position covers a single label directly beneath ops.example.","This is outside the ops.example subtree named by the certificate."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-010","objective":"1.4","concept":"Key-management versus workload identity","prompt":"An application calls a central service to create, rotate, and revoke encryption keys. The requirement now adds that key material must be protected in tamper-resistant hardware. Which pair BEST distinguishes the two requirements?","options":["Certificate authority for symmetric-key rotation; secure enclave for every external client's keys","Key escrow for routine lifecycle; TPM for organization-wide shared signing","HSM for all business access decisions; directory for hardware key protection","Key management system for lifecycle; HSM for hardware protection"],"explanations":["A CA issues certificates, and a local enclave is not the general organization-wide lifecycle service.","Escrow concerns recovery custody, and a device TPM is not ordinarily a central shared signing appliance.","An HSM protects cryptographic operations; directory authorization is not tamper-resistant key storage.","A KMS manages lifecycle and access; a hardware security module can protect keys and cryptographic operations."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-011","objective":"1.4","concept":"Hashing versus keyed authenticity","prompt":"Two systems share a secret and need to detect both message changes and messages forged by outsiders. They do not need third-party proof of who sent a message. Which mechanism BEST fits?","options":["A keyed message authentication code","An unkeyed hash sent with the message","Symmetric encryption without an integrity check","A public checksum posted beside the message"],"explanations":["A MAC uses a shared secret to authenticate message integrity without public verifiability.","An outsider can replace both the message and its unkeyed hash.","Encryption alone does not necessarily authenticate modifications.","A public checksum does not bind the message to a secret-holding sender."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-012","objective":"1.4","concept":"Encryption key rotation compromise","prompt":"A storage encryption key is exposed. The team changes only the key's label in its configuration and leaves the underlying key bytes unchanged. Which action is still required to address the compromise?","options":["Rotate the alias and restrict new encryption operations while old ciphertext uses the exposed key","Generate new key material and migrate protection of affected data as appropriate","Wrap the same compromised data key with a new key-encryption key only","Rotate the service's authentication password while leaving the exposed data key unchanged"],"explanations":["That may stop future use but does not remove the attacker's ability to decrypt exposed-key ciphertext.","Relabeling does not change the secret an attacker already has.","An attacker who already knows the data key does not need to unwrap it.","Service authentication is separate from knowledge of the data decryption key."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-013","objective":"2.1","concept":"Capability versus claimed identity","prompt":"A group posts political slogans while selling stolen account access on criminal forums. Analysts have only those observations. Which assessment BEST separates evidence from assumption?","options":["Selling access proves the group is state sponsored","Political messaging excludes any financial motive","Financial gain is evidenced; the slogans alone do not prove ideological motivation","The account sales prove all members were internal employees"],"explanations":["A commercial criminal activity does not identify sponsorship.","Actors can combine motives or use messaging as cover.","Observed sale of access supports a financial objective, while claims can be misleading.","Stolen access can originate from external compromise."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-014","objective":"2.1","concept":"Insider versus compromised insider account","prompt":"A valid employee account exports sensitive files at an unusual hour. The employee denies making the request. What is the BEST initial classification?","options":["Authorized activity because the account had export permission","Confirmed malicious insider activity by that employee","Confirmed external intrusion because the employee denies involvement","Suspicious account activity requiring investigation of both misuse and compromise"],"explanations":["Permission does not establish that this use was intended or legitimate.","A valid account can be hijacked, so the human attribution is premature.","Denial is relevant but does not establish the cause.","Account attribution alone does not prove which human or process controlled it."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-015","objective":"2.2","concept":"QR-based credential theft","prompt":"A sticker replaces the payment QR code on a parking meter. The replacement opens a convincing site that collects card details. Which description BEST identifies the attack path?","options":["Physical replacement directs victims to a fraudulent online service","DNS poisoning at the legitimate payment service","A TLS downgrade on a session to the genuine portal","A browser session fixation attack against the genuine payment site"],"explanations":["The attacker uses a physical artifact to deliver a malicious destination.","The QR destination was replaced; no resolver or authoritative DNS manipulation is shown.","The victim visits a fraudulent destination rather than a demonstrated downgraded genuine session.","Collecting details on a different site does not establish forced use of a known genuine-site session."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-016","objective":"2.2","concept":"Managed provider concentration","prompt":"An attacker compromises an MSP's remote-management console and uses its authorized connections to deploy malware to several customers. Which control MOST directly limits cross-customer impact?","options":["Trust all sessions from the console because its source IP is approved","Separate customer administration privileges and constrain remote-management reach","Require MFA only for customer users while leaving the console's service authority unrestricted","Use a common administrative identity across customers to centralize auditing"],"explanations":["The compromised console is itself the trusted source being abused.","Compartmentalization reduces the blast radius of one management compromise.","That does not compartmentalize the compromised management service.","Common authority preserves a wide cross-customer blast radius."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-017","objective":"2.2","concept":"Voice impersonation verification","prompt":"A caller sounding like the finance director requests an urgent MFA reset. The help desk has no existing ticket. Which action BEST verifies authorization without relying on the potentially forged voice?","options":["Send the reset approval to a new number supplied during the call","Verify the caller using information available in the company's public staff directory","Use the established identity-verification and independently sourced callback process","Approve a short-lived reset and audit the resulting sign-in afterward"],"explanations":["The request itself cannot establish a trusted verification destination.","Public details can be obtained by an impersonator.","Independent verification avoids trusting a voice or contact information supplied in the request.","That gives access before completing the required identity verification."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-018","objective":"2.2","concept":"Malicious removable media","prompt":"An unknown USB device appears as a keyboard and rapidly types commands when connected, although storage scanning finds no files. Which preventive control BEST addresses this mechanism?","options":["Allow all USB keyboards while restricting only high-capacity storage","Disable autorun on all removable storage","Scan only the USB device's exposed storage for malicious files","Restrict unapproved USB device classes and enrollment"],"explanations":["That explicitly leaves the abused device class unrestricted.","A keyboard-emulating device delivers input without storage autorun.","The device may operate as an input peripheral without any stored payload file.","The device abuses an input-device interface, so storage-only scanning misses the mechanism."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-019","objective":"2.3","concept":"Server-side URL fetching","prompt":"A preview feature accepts a URL. An attacker supplies an internal address, and the application's server retrieves an administrative page that the attacker cannot reach directly. Which flaw BEST describes this?","options":["Server-side request forgery","Cross-site request forgery","Reflected cross-site scripting","SQL injection"],"explanations":["SSRF abuses the server's network reach through attacker-controlled fetch destinations.","CSRF makes a victim's browser submit an authenticated request; this fetch is by the server.","No script execution in a victim browser is described.","The attacker changes a fetch target, not the structure of a database query."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-020","objective":"2.3","concept":"Memory safety evidence","prompt":"A service crashes only when a supplied field exceeds its allocated length. A debugger shows that adjacent control data was overwritten. Which mitigation MOST directly addresses the coding flaw?","options":["Use SQL parameterization for every database request made by the service","Enforce bounds and use memory-safe handling for that input","Validate only the field's permitted characters without enforcing its maximum length","Add exception handling around the crash without correcting the unsafe write"],"explanations":["That protects database query structure, not the described out-of-bounds memory write.","The root failure is writing beyond allocated memory.","Permitted characters can still overflow the allocated length.","Handling failure does not prevent corruption of adjacent memory."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-021","objective":"2.3","concept":"Resource reuse disclosure","prompt":"A newly assigned cloud volume contains fragments of a previous tenant's records. No live connection to that tenant exists. Which failure BEST explains the exposure?","options":["An overly broad network security group permitting intertenant traffic","A live hypervisor escape from the previous tenant's still-running guest","Inadequate sanitization before storage resource reuse","An application-level authorization failure in the old tenant's API"],"explanations":["Network connectivity is not necessary to read remnants already on the assigned volume.","The evidence is residual data on reassigned storage without live access.","Residual data survived reassignment of the underlying resource.","The new tenant reads local fragments, not the old API."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-022","objective":"2.3","concept":"Side-loading versus jailbreaking","prompt":"A user installs an application package from an unapproved website using the phone's permitted external-install option. The operating system's privilege restrictions remain intact. Which term is MOST precise?","options":["A malicious firmware update","Jailbreaking","Privilege escalation through a kernel exploit","Sideloading"],"explanations":["An application package is not evidence of firmware replacement.","The operating system's privilege restrictions remain intact, unlike a restriction-removal jailbreak.","The scenario specifies use of a permitted installation option, not an exploit.","The application was installed outside the approved store without evidence of defeating operating system restrictions."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-023","objective":"2.3","concept":"Zero-day scope","prompt":"A previously unknown software flaw is being exploited before the vendor has released a fix. Which statement BEST captures why ordinary patch deployment cannot yet resolve it?","options":["No vendor correction for this flaw is currently available, so interim controls are needed","Only outdated installations are at risk, so the latest normal patch proves safety","Network isolation permanently remediates the software defect","Signature detection is guaranteed to catch it once the vendor is notified"],"explanations":["A zero-day situation can require exposure reduction and detection before a patch exists.","A previously unknown flaw can affect fully updated supported software.","Isolation mitigates reachability but does not repair the vulnerable code.","Notification does not immediately guarantee a reliable signature or coverage."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-024","objective":"2.4","concept":"Password spray pacing","prompt":"Across six hours, logs show two password candidates tried against 900 accounts, with long delays between attempts on any one account. What does the pacing MOST likely attempt to avoid?","options":["Avoid a per-session idle timeout while cracking hashes offline","Per-account lockout thresholds while testing common passwords","Maximize guesses on one account before moving to the next","Reuse a different previously leaked password for every account"],"explanations":["Live attempts across accounts are inconsistent with offline hash cracking.","Distributed attempts across accounts keep individual failure counts low.","The pattern deliberately spreads a small candidate set across many accounts.","That describes credential stuffing rather than the two common candidates shown."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-025","objective":"2.4","concept":"Impossible travel limitations","prompt":"A user appears to log in from two distant countries within five minutes. One address belongs to the company's known VPN egress. What should an analyst do NEXT?","options":["Allowlist all activity from both countries for the user indefinitely","Disable the account automatically based only on the country difference","Correlate device, session, and VPN evidence before concluding account takeover","Treat any session using company VPN egress as inherently trusted"],"explanations":["A current routing explanation does not justify suppressing future unexplained activity.","The known VPN egress is context that should be assessed before treating distance as proof.","Egress geography can differ from physical location, so context is needed.","A compromised account can also use legitimate VPN infrastructure."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-026","objective":"2.4","concept":"Beacon pattern interpretation","prompt":"A server sends a small HTTPS request to a newly registered domain every 61 seconds, including overnight. The interval is consistent and unrelated to scheduled jobs. What is the BEST initial hypothesis?","options":["An inbound reflection attack saturating the server","Confirmed bulk data exfiltration based solely on regular timing","A normal update check that should be allowlisted immediately","Possible command-and-control beaconing requiring process and destination investigation"],"explanations":["The observed direction and small periodic requests do not match that availability pattern.","Periodic callbacks warrant investigation but do not identify the transferred content.","A plausible benign use still needs validation given the unexplained process and new domain.","Regular unexplained outbound callbacks are suspicious, but need corroboration."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-027","objective":"2.4","concept":"Lateral movement corroboration","prompt":"After a suspicious sign-in, one workstation creates remote services on three peer systems using an administrative account. Which evidence would BEST corroborate lateral movement?","options":["Matching remote-service creation and process-launch events on the destination hosts","A successful login on the original workstation with no destination evidence","An internal port scan from the same workstation","A matching username in the directory without host or session correlation"],"explanations":["Destination execution tied to the source supports movement beyond an initial foothold.","That establishes local account use, not execution on peers.","Scanning suggests discovery but is less direct than evidence of remote execution.","A directory entry does not demonstrate actions across the destination systems."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-028","objective":"2.4","concept":"Ransomware versus destructive attack","prompt":"An attacker overwrites file contents with random data and leaves a payment demand. Analysis finds no encryption key or reversible transformation. What is the MOST accurate description?","options":["Recoverable encryption proven solely by the demand for payment","Destructive activity presented as ransomware; payment may not enable recovery","A confidentiality-only incident because a note mentions stolen files","A normal secure-erase workflow because the overwrite uses random data"],"explanations":["A payment demand is not evidence of reversible cryptography.","A ransom note does not prove that the destroyed data is cryptographically recoverable.","The established overwriting directly affects integrity and availability regardless of unverified claims.","The unauthorized destructive act and extortion context are not an approved sanitization procedure."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-029","objective":"2.4","concept":"On-path certificate warning","prompt":"On one public Wi-Fi network, several unrelated HTTPS sites suddenly present certificates signed by an unknown local issuer. The same devices validate those sites normally on cellular. What should be investigated FIRST?","options":["Every client's root trust store independently lost the same public roots only on Wi-Fi","All affected public sites simultaneously forgot to renew their certificates","Potential TLS interception on that network","A DNS cache expiry alone changed the certificate issuer without changing the responding endpoint"],"explanations":["The network-specific issuer replacement is more consistent with interception than such independent changes.","Successful validation on cellular contradicts a uniform site-side renewal issue.","A network-specific issuer change across unrelated sites suggests interception or a local inspection mechanism.","DNS expiry by itself does not alter a genuine server's TLS certificate."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-030","objective":"2.4","concept":"Malicious persistence through identity","prompt":"A cloud account's password is reset after compromise, but a maliciously authorized application's long-lived access remains valid. What should responders investigate and revoke?","options":["Only the local browser's saved-password database","Only the password-reset timestamp in the employee directory","Only the user's enrollment in password-complexity policy","Unauthorized application grants and surviving tokens or sessions"],"explanations":["The malicious application's independent cloud access can persist without local saved passwords.","A timestamp does not revoke a separately authorized application grant.","Password quality controls do not invalidate surviving delegated access.","Password changes may not invalidate every delegated grant and token."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-031","objective":"2.5","concept":"Segmentation enforcement","prompt":"Two server groups use different IP subnets, but routing permits all traffic between them. Management calls this containment against lateral movement. What is missing?","options":["Enforced access restrictions between the groups","More precise subnet masks with the same unrestricted routing policy","Separate VLAN labels while allowing all inter-VLAN sessions","A common shared administrator account on both server groups"],"explanations":["Separate address ranges without policy enforcement do not meaningfully limit reachable services.","Address boundaries alone still do not restrict reachability.","Logical separation without filtering preserves the same lateral paths.","Shared credentials can make lateral movement easier, not restrict it."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-032","objective":"2.5","concept":"Patch exception lifecycle","prompt":"A vendor forbids patching an appliance during its certified operating cycle. A temporary isolation control is approved. Which action BEST prevents the workaround from becoming unmanaged permanent risk?","options":["Close the finding as remediated once isolation is confirmed","Assign an owner, review date, monitoring, and a replacement or remediation path","Keep the isolation rule indefinitely without testing its continued effectiveness","Remove the asset from recurring scans until the vendor permits patching"],"explanations":["The underlying vulnerable software remains and needs ongoing management.","A compensating control needs lifecycle management and reassessment of residual risk.","A temporary workaround requires review and evidence, not an unbounded assumption.","That hides changes in exposure and mitigation effectiveness."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-033","objective":"2.5","concept":"Hardening attack paths","prompt":"A workstation user can install arbitrary browser extensions, and a malicious extension reads authenticated business pages. Which control MOST directly addresses this path?","options":["Apply URL filtering only to the extension store's homepage","Require stronger TLS ciphers for business web applications","Allow only approved extensions with controlled permissions","Require users to reauthenticate more often while permitting all extensions"],"explanations":["Extensions can be installed from other sources or misbehave after installation.","A malicious browser extension can access authorized content after transport decryption.","Extension policy addresses the untrusted code running inside the browser context.","An extension can still observe or act within each valid session."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-034","objective":"2.5","concept":"Isolation versus disabling security visibility","prompt":"An infected endpoint must be separated from production traffic, but responders still need remote telemetry. Which containment choice BEST balances those needs?","options":["Stop the endpoint agent after issuing its first alert","Disconnect every interface even though controlled isolation is available","Leave business access enabled but block only the initially observed malicious domain","Restrict network access while retaining the approved response-management channel"],"explanations":["Removing the response agent sacrifices the required continuing telemetry.","That unnecessarily eliminates the specified remote response channel.","That may leave lateral movement and alternate destinations available.","Selective isolation can stop harmful traffic without losing the authorized response connection."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-035","objective":"3.1","concept":"SaaS shared responsibility nuance","prompt":"A SaaS provider patches its application promptly. A customer's administrator configures a document workspace as publicly readable. Who should MOST directly correct that setting?","options":["The customer controlling workspace permissions","The provider alone, because all security is outsourced under SaaS","The employee downloading a document, because access implies permission to change policy","The identity provider alone by changing every user's password"],"explanations":["Provider patching does not replace the customer's configuration and data-access responsibilities.","SaaS does not transfer tenant-controlled sharing decisions to the provider.","A consumer of a public link may lack authority over workspace settings.","Anonymous public sharing may not require those credentials at all."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-036","objective":"3.1","concept":"Air-gap residual risk","prompt":"A disconnected industrial network receives monthly updates through removable media carried by technicians. Which statement BEST describes its remaining attack surface?","options":["The air gap makes validating update authenticity unnecessary","The transfer workflow can bridge the isolation and needs controlled media validation","Scanning the technician's email alone eliminates the media-import risk","The only necessary control is hiding the isolated network's IP addresses"],"explanations":["Offline import can still introduce modified software.","An air gap reduces network paths but does not eliminate physical data-transfer risk.","Email scanning does not establish the safety of the actual transferred media.","Address secrecy does not secure a physical import channel."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-037","objective":"3.1","concept":"Hybrid connectivity exposure","prompt":"An organization links its cloud environment and data center with a private circuit. Administrators assume encryption and per-resource authorization are no longer needed. Which criticism is BEST?","options":["A private circuit guarantees end-to-end encryption without inspecting its service design","Private routing automatically enforces application-level least privilege","A private path does not replace confidentiality controls or least-privilege authorization","Every identity on either side can be trusted once one circuit endpoint is authenticated"],"explanations":["Private connectivity and encryption are different properties.","Network reachability is not per-resource authorization.","Connectivity type does not inherently protect every segment or authorize every resource interaction.","Endpoint connectivity does not authorize every workload and user."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-038","objective":"3.1","concept":"Immutable deployment tradeoff","prompt":"Servers are replaced from approved images rather than manually repaired in place. Investigators need evidence before an automated replacement destroys a compromised instance. Which process adjustment BEST supports both goals?","options":["Retain only deployment templates because they describe every runtime change","Collect only the approved image hash after the compromised instance is destroyed","Treat the replacement's fresh logs as a complete record of the old instance","Capture required telemetry and forensic artifacts before authorized instance replacement"],"explanations":["Templates describe intended infrastructure, not all compromised runtime behavior.","The image hash cannot reconstruct the running instance's volatile evidence.","New instance logs do not preserve earlier activity unless collected separately.","Immutable recovery can coexist with a deliberate evidence-preservation step."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-039","objective":"3.2","concept":"Application versus network segmentation","prompt":"Two applications share a server subnet. Only the order service may call the payment service's API. Which design BEST enforces that requirement even when another host in the subnet is compromised?","options":["Authenticate service identities and authorize the specific service-to-service request","Use a subnet-level allow rule for all peers and rely only on TLS encryption","Move payment into another subnet but allow the original entire subnet to call its API","Require application users to rotate passwords while leaving service calls unauthenticated"],"explanations":["Identity-aware authorization avoids treating subnet membership as sufficient trust.","Encryption does not prove that a permitted peer is the authorized order service.","That still authorizes the compromised peer's network path.","User password rotation does not establish service identity or authorization."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-040","objective":"3.2","concept":"802.1X component responsibility","prompt":"An employee's laptop presents credentials to a switch port. The switch relays the exchange to a RADIUS service and opens the port only after an accept result. Which component is the authenticator?","options":["The employee's laptop","The access switch","The RADIUS service","The directory storing the user's account"],"explanations":["The laptop acts as the supplicant requesting admission.","In 802.1X, the authenticator controls the port; RADIUS carries the back-end authentication exchange.","The back-end service is the authentication server, distinct from the port-controlling authenticator.","The directory may supply identity information but does not control that switch port."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-041","objective":"3.2","concept":"Wireless authentication design","prompt":"A company must revoke one employee's Wi-Fi access without changing credentials on every other device. Which design BEST supports this requirement?","options":["A hidden network name plus the current shared passphrase","A shared WPA3 passphrase with an annual rotation schedule","Enterprise wireless authentication with individual identities","A MAC allowlist without user or device credential authentication"],"explanations":["Network-name hiding does not establish individual identities.","Shared credentials prevent individual credential revocation despite strong radio encryption.","Individual authentication allows targeted revocation instead of rotating one shared secret.","MAC addresses can be copied and are not a strong individual credential."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-042","objective":"3.2","concept":"Secure administrative access path","prompt":"A supplier needs temporary access to one internal server. Policy requires session recording and forbids direct inbound access to that server from the internet. Which design BEST fits?","options":["A supplier account on the target with unrestricted standing access","A port forward to the target protected by MFA","A broad VPN with shared credentials and no session recording","A controlled jump host with scoped access and recorded sessions"],"explanations":["A target account alone does not create the controlled recorded intermediary path.","MFA does not change the prohibition on direct inbound access to that server.","That fails both scope and accountability requirements.","An intermediary can enforce the restricted administrative path and accountability requirements."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-043","objective":"3.2","concept":"Cloud access control placement","prompt":"Employees use several SaaS applications from managed browsers. The company needs consistent visibility into risky cloud-app use and controls over sensitive uploads. Which capability BEST matches this requirement?","options":["A CASB integrated with the relevant cloud access paths","A WAF protecting only the company's own public website","A network access-control check used only when joining office Wi-Fi","A VPN concentrator that routes traffic without application or content policy"],"explanations":["A cloud access security broker applies visibility and policy to cloud service use.","A web application firewall there does not govern employee use of external SaaS applications.","NAC admission checks do not by themselves provide ongoing SaaS data-use policy.","Routing alone lacks the requested SaaS visibility and upload controls."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-044","objective":"3.3","concept":"Classification-driven handling","prompt":"A dataset combines publicly available ages and locations into records that can identify specific people when linked with an internal customer ID. Which handling decision is BEST?","options":["Classify it as public based on the original source of the age and location fields","Assess the combined dataset's sensitivity and apply controls to its identification risk","Treat access permissions as the classification and skip evaluating the combined content","Classify only the customer ID column and permit unrestricted export of joined records"],"explanations":["The joined internal identifier can change reidentification risk.","Aggregation and linkage can make a combined dataset more sensitive than isolated public fields.","Permissions enforce handling but do not determine intrinsic sensitivity.","The combined record still supports identification through linkage."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-045","objective":"3.3","concept":"Data retention minimization","prompt":"An analytics team wants to keep raw identifiable clickstream data indefinitely, although its approved use needs only 90 days of individual history and longer-term aggregate trends. Which approach BEST meets the need with less exposure?","options":["Replace names with stable reversible tokens and retain the full mapping indefinitely","Keep identifiable raw records indefinitely but restrict them to one administrator","Expire raw identifiers after the approved period and retain appropriately de-identified aggregates","Keep raw data in an encrypted archive forever and call it deleted"],"explanations":["Reversible identifiable history still exceeds the stated raw-data need.","Access limits help, but retain unnecessary long-term exposure.","This preserves the stated analysis while limiting unnecessary identifiable history.","Encryption is protection, not deletion or minimization of retained data."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-046","objective":"3.3","concept":"Transport encryption endpoint boundary","prompt":"A user sends confidential data over HTTPS to an approved portal. The portal writes request bodies to a broadly readable plaintext debug log. Where should the corrective control focus?","options":["Pin the portal certificate in the browser while leaving logging unchanged","Strengthen the browser-to-portal cipher without changing the logging code","Require mutual TLS but retain the same broadly readable request-body logs","The receiving application's logging and access configuration"],"explanations":["Pinning affects server authentication, not the server's handling of plaintext.","Stronger transit encryption does not prevent plaintext logging after decryption.","Client authentication does not control post-termination logging.","TLS ends at the receiving service; its later plaintext handling remains a separate responsibility."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-047","objective":"3.3","concept":"Data ownership versus custodianship","prompt":"A storage team configures access and backups according to rules set by the business owner. A new request would broaden access to sensitive records. Who should decide whether that access is appropriate?","options":["The accountable data owner through the authorization process","The custodian alone because it has permission to administer the database","The requesting team's newest employee because the request concerns their work","The data processor's hosting vendor without consulting the owner"],"explanations":["Custodians implement protection; the owner determines appropriate business access and handling requirements.","Implementation authority is not necessarily business authorization authority.","A requester still needs approval under the ownership process.","Hosting and processing roles do not independently set business-access policy."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-048","objective":"3.4","concept":"RTO versus RPO tradeoff","prompt":"A system restores service in 50 minutes using data that is 40 minutes old. Its RTO is 60 minutes and its RPO is 15 minutes. Which result is correct?","options":["RTO missed; RPO met","RTO met; RPO missed","Both objectives met","Both objectives missed"],"explanations":["This reverses downtime and recoverable-data-age measurements.","Recovery time is within 60 minutes, but the recoverable data is older than the allowed 15 minutes.","The 40-minute data gap exceeds the RPO.","The 50-minute restoration is within the RTO."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-049","objective":"3.4","concept":"Site recovery dependency","prompt":"A warm site has servers and connectivity, but rebuilding application configuration from tape takes 18 hours. The required restoration time is four hours. Which improvement BEST addresses the gap?","options":["Upgrade only the alternate site's internet link when tape reconstruction is the bottleneck","Increase the frequency of production backups without reducing restore preparation time","Pre-stage and validate the application configuration and necessary data at the recovery site","Reclassify the facility as a hot site in the plan"],"explanations":["An unrelated link upgrade does not address the stated limiting step.","Fresher backups can improve RPO but do not necessarily fix the 18-hour RTO bottleneck.","Recovery readiness must eliminate the configuration/data preparation that exceeds the target.","Recovery capability must change, not merely its label."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-050","objective":"3.4","concept":"Backup immutability versus access","prompt":"A ransomware operator compromises the same administrator identity used for production and backup management. Which design MOST directly protects recoverability against that identity?","options":["Hide backup deletion in the UI while allowing it through the same administrator API","Increase snapshot frequency but let the same administrator delete all snapshots","Replicate backups immediately to another writable repository using the same identity","Separately administered immutable backups with tested restoration"],"explanations":["A UI restriction does not constrain the actual privileged capability.","The compromised identity retains destructive access to every new copy.","Location diversity alone does not remove shared administrative exposure.","Separated authority and enforced retention reduce the attacker's ability to destroy recovery copies."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-051","objective":"3.4","concept":"Resilience testing method","prompt":"During an exercise, production remains at the main site while the recovery team restores and operates a duplicate workload at the alternate site. Which exercise type BEST fits?","options":["Parallel processing test","Tabletop exercise","Full interruption test","Document review"],"explanations":["The alternate environment runs alongside the production workload without a full operational cutover.","This scenario executes systems rather than only discussing decisions.","Production has not been deliberately cut over or interrupted.","A running duplicate workload goes beyond reviewing written plans."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-052","objective":"3.4","concept":"Geographic independence","prompt":"A company uses two data centers on opposite sides of one city. Both depend on the same regional floodplain and electrical substation. What is the MOST significant limitation?","options":["The distance guarantees independence because the buildings have different addresses","A regional event could disable both sites despite building separation","The second site cannot help with any isolated server failure","Synchronous replication alone eliminates the shared power and flood exposure"],"explanations":["Different addresses can share regional hazards and supporting infrastructure.","Geographic distance must be assessed against shared hazards and infrastructure.","It may help local failures; the concern is correlated regional loss.","Data synchronization does not remove physical dependency on common infrastructure."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-053","objective":"4.1","concept":"Secure boot versus disk encryption","prompt":"An attacker modifies a laptop's pre-OS boot component to capture a disk-unlock secret. Which control MOST directly helps detect or block unauthorized boot code?","options":["Application allowlisting only after the operating system has loaded","Full-disk encryption without validating code that receives the unlock secret","A verified or measured boot chain anchored in trusted hardware","A signed antivirus update installed inside the operating system"],"explanations":["The modified code runs before that policy takes effect.","A malicious boot component can capture the secret before normal protections apply.","Boot integrity controls address unauthorized pre-OS changes; measured states can inform key release.","That does not itself authenticate the pre-OS boot component."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-054","objective":"4.1","concept":"Sandboxing versus signature detection","prompt":"An email attachment has no known malicious signature. Analysts want to observe whether it spawns processes or attempts outbound communication before release. Which technique BEST fits?","options":["Run the attachment on a production endpoint with logging enabled","Repeat the same static signature scan without changing intelligence or inputs","Inspect only the sender's domain reputation","Execute it in an isolated analysis sandbox"],"explanations":["Logging alone does not provide the required safe execution isolation.","That repeats an already inconclusive test and does not observe behavior.","Sender reputation does not establish the attachment's execution behavior.","Behavioral detonation reveals actions in a controlled environment without relying only on known signatures."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-055","objective":"4.1","concept":"Application input trust","prompt":"A web form validates numeric invoice IDs in browser JavaScript. Direct API calls still accept arbitrary strings and alter query behavior. What change BEST addresses the missing boundary?","options":["Enforce server-side validation and parameterized database access","Add stricter checks only in the browser's JavaScript","Escape only HTML output while keeping dynamically concatenated SQL","Require HTTPS for every API request without changing input handling"],"explanations":["The server must not trust client checks, and parameters keep input separate from SQL structure.","Direct API calls can still bypass them.","Output encoding addresses browser interpretation, not SQL query construction.","Transport security does not make attacker-controlled input trustworthy."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-056","objective":"4.2","concept":"Asset lifecycle and secrets","prompt":"A cloud VM is deleted, but its static service credential remains valid and appears in an old image export. What should decommissioning also include?","options":["Delete the original VM's disk but leave its independent credential valid","Revoke or rotate associated credentials and reconcile dependent resources","Remove the hostname from DNS and stop the instance's network interface","Expire the credential only when the next replacement system is deployed"],"explanations":["The old export can still expose a usable secret.","Deleting compute does not automatically invalidate independently issued secrets.","The credential may work from elsewhere independently of that host.","That leaves an unnecessary valid access path during the intervening period."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-057","objective":"4.2","concept":"Inventory source conflict","prompt":"An endpoint inventory lists software as removed, but an authenticated scan finds its service running on a laptop. Which response BEST resolves the discrepancy?","options":["Suppress that scanner plugin to eliminate the discrepancy","Accept the inventory status because the uninstall ticket was closed","Validate the live state and reconcile the inventory and management workflow","Reinstall the approved baseline on every laptop before checking the finding"],"explanations":["Suppression hides the conflicting evidence rather than resolving it.","A closed ticket is not proof that the live service is absent.","Operational evidence conflicts with the record and requires verification of both sources.","Broad reimaging is disproportionate before validating the specific live-state discrepancy."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-058","objective":"4.3","concept":"Authenticated scan coverage","prompt":"An unauthenticated scan finds open ports but misses missing local security updates that an authenticated scan detects. What BEST explains the difference?","options":["An authenticated scan bypasses the need to verify scanner privileges and coverage","An authenticated scan is automatically an exploitation test","The unauthenticated scan's zero local findings prove those updates were installed","Credentialed access exposes local package and configuration evidence unavailable remotely"],"explanations":["Credentialed checks still depend on actual permissions and successful collection.","Access to local evidence does not imply active exploitation.","A tool cannot prove what it lacked the coverage to inspect.","Authenticated scanning can inspect host state beyond network-visible services."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-059","objective":"4.3","concept":"False negative interpretation","prompt":"A scan reports no findings on a server, but its output says authentication failed and several checks were skipped. How should the result be interpreted?","options":["Coverage is incomplete, so the result cannot establish that those checks passed","Zero findings means all controls passed despite skipped checks","Every skipped item should be marked a confirmed exploitable finding","The incomplete result can replace a prior authenticated assessment without qualification"],"explanations":["Skipped checks are unknown, not successful tests.","Skipped checks provide no pass evidence.","Uncertainty is not proof of every possible vulnerability.","Coverage differences must be considered before comparing or replacing evidence."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-060","objective":"4.3","concept":"Remediation versus compensating measure","prompt":"A public application cannot be patched until its vendor release arrives. A WAF rule blocks the known exploit pattern. How should the finding be tracked?","options":["Closed as remediated after a single known exploit request is blocked","Open with mitigation evidence and residual-risk review until remediation is verified","Accepted indefinitely because the application remains available behind the WAF","Transferred to the WAF vendor with no remaining application-owner responsibility"],"explanations":["Blocking one pattern does not repair the underlying vulnerability.","A web application firewall rule reduces exposure but does not fix the underlying code.","Continuing service does not establish authorized long-term risk acceptance.","Using a control does not automatically transfer ownership of the vulnerable application risk."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-061","objective":"4.4","concept":"Time normalization","prompt":"A firewall records UTC and an endpoint records local time without an offset. A SIEM timeline appears to show the endpoint action before the triggering connection. What should be checked FIRST?","options":["Discard one source because its local display time differs","Reorder events manually to match the analyst's first hypothesis","Clock synchronization and timezone normalization across sources","Increase the correlation window indefinitely without validating clocks"],"explanations":["The data may be valid after timezone normalization.","That risks forcing a false sequence rather than fixing the time basis.","Inconsistent timestamps can create a false event order.","A broad window can mask the issue and create false associations."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-062","objective":"4.4","concept":"Correlation versus aggregation","prompt":"A platform stores all authentication events centrally but alerts only when one event is explicitly labeled 'critical.' Analysts want to detect a sequence of low-severity events across hosts. What capability is missing?","options":["A duplicate collector forwarding the same events to the same rule","More storage and a longer retention period without new detection rules","A rule that raises every individual event to critical severity","Cross-event correlation using defined detection logic"],"explanations":["Duplicate ingestion does not supply missing correlation logic.","Retention improves available history, but does not define cross-event logic.","That creates noise rather than recognizing the specific sequence.","A meaningful sequence can be suspicious even when individual events have low severity."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-063","objective":"4.4","concept":"Alert triage context","prompt":"An administrative tool triggers an alert on a server. It is expected during approved maintenance, but today's use is outside the window and comes from a new account. What is the BEST triage approach?","options":["Investigate the unusual identity and timing rather than suppressing the tool universally","Allow the event because the executable is signed and appears in inventory","Escalate the tool itself as malware without examining the account or execution chain","Suppress the alert by extending the maintenance window retrospectively"],"explanations":["Legitimate tools can be abused; context distinguishes approved activity from possible misuse.","Legitimate administrative tools can still be used without authorization.","The anomaly concerns use and context, not proof that the signed binary is malicious.","Changing the expected window does not validate the unexplained activity."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-064","objective":"4.5","concept":"ACL first-match analysis","prompt":"A firewall evaluates rules top-down and stops at the first match. Rule 1 allows subnet 10.20.0.0/16 to database port 5432. Rule 2 denies host 10.20.4.9 to that port. The host still connects. Why?","options":["Host-specific rules always override subnet rules regardless of position","The broader allow rule matches before the host-specific deny","The later deny is applied only to UDP on the same port","Established sessions are always immune to all firewall rules"],"explanations":["The scenario explicitly uses top-down first-match evaluation.","First-match evaluation never reaches the later deny for this traffic.","No protocol distinction supporting that conclusion was specified.","Some state behavior matters, but the stated initial matching problem is the broad earlier allow."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-065","objective":"4.5","concept":"Mail forwarding authentication","prompt":"Legitimate forwarded mail fails SPF. Its aligned DKIM signature also fails because a forwarding gateway appends a footer to the signed body. What change BEST preserves authentication without weakening recipient policy?","options":["Set the original sender's DMARC policy to no enforcement permanently","Publish the forwarder's address only in the forwarder's unrelated SPF domain","Stop modifying the signed content so the original aligned DKIM signature can survive","Extend the DKIM key length but continue modifying the signed body"],"explanations":["That weakens handling of unauthorized mail instead of preserving the legitimate signature.","That does not align SPF with the original visible From domain or fix the changed signed body.","A surviving aligned DomainKeys Identified Mail signature can satisfy DMARC even when forwarding breaks SPF.","A stronger signing key does not make modified signed content verify."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-066","objective":"4.5","concept":"SFTP versus FTPS constraints","prompt":"A partner permits a single SSH-based file-transfer service on TCP 22 and forbids FTP control/data channels. Which protocol meets the requirement?","options":["HTTPS file upload","FTPS","FTP tunneled through a VPN","SFTP"],"explanations":["HTTPS may transfer files securely but does not meet the required SSH-based service interface.","FTP over TLS is encrypted but not the specified SSH-based file-transfer protocol.","A VPN protects transport but does not turn FTP control/data channels into the required service.","SSH File Transfer Protocol uses the SSH transport rather than FTP's separate control/data design."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-067","objective":"4.5","concept":"Endpoint detection versus perimeter controls","prompt":"A laptop is off the corporate network when a trusted process begins injecting code into another process. Which control is BEST positioned to observe and contain this local behavior?","options":["EDR running on the laptop","A perimeter IDS with no agent or remote telemetry","A DNS filtering service evaluating only requested domain names","A web application firewall protecting the company's public portal"],"explanations":["Endpoint detection and response can inspect process behavior and act on the device away from the office perimeter.","It lacks access to the laptop's local process activity away from the perimeter.","DNS decisions do not directly observe injection between processes.","That WAF inspects the portal's requests rather than local laptop processes."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-068","objective":"4.6","concept":"Service identity lifecycle","prompt":"An application runs scheduled tasks under a former employee's personal account. Disabling that account breaks production. Which redesign BEST removes the dependency?","options":["Keep the departed employee's account but rotate its password into a vault","Use a dedicated, scoped, managed service identity with an accountable owner","Move all tasks to the newest employee's account","Use a shared domain-admin account for every scheduled workload"],"explanations":["Secret custody improves, but the service still depends on a departed person's identity.","The workload should have a lifecycle independent of an individual's employment.","That repeats the same employment-lifecycle dependency.","A shared highly privileged identity creates excessive authority and poor accountability."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-069","objective":"4.6","concept":"Access recertification evidence","prompt":"An employee changed departments and accumulated old and new entitlements. Authentication works correctly. Which activity MOST directly identifies permissions that should be removed?","options":["A role assignment check against the employee's original department only","An authentication log review limited to failed password attempts","An access review against current job duties and approved ownership","A check that every permission was approved at some point in the past"],"explanations":["The current job, not just the original role, determines continuing business need.","Failed logins do not assess whether existing entitlements remain justified.","Recertification assesses continued authorization and catches privilege accumulation.","Past approval does not establish present need after a transfer."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-070","objective":"4.6","concept":"Biometric threshold tradeoff","prompt":"A facility tightens a biometric matching threshold to reduce impostor acceptance. What side effect should it expect to assess?","options":["The false acceptance rate should rise while false rejections fall","False rejections should decrease because a stricter threshold accepts more genuine variations","False accepts and false rejects should both decrease automatically","An increased false rejection rate for legitimate users"],"explanations":["That describes the usual effect of loosening, rather than tightening, the threshold.","A stricter threshold generally accepts fewer matching variations, not more.","Threshold adjustment normally trades one type of error against the other.","A stricter match requirement can reject more genuine attempts while reducing false accepts."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-071","objective":"4.6","concept":"Session revocation versus password reset","prompt":"A user reports a stolen authenticated browser session. The password is reset, but the application continues accepting the existing session cookie. What is the MOST direct additional action?","options":["Revoke the affected sessions or tokens at the application or identity service","Require MFA only at the next new login while leaving the current session valid","Clear saved passwords on the legitimate user's computer only","Shorten future session lifetimes but leave the stolen session unchanged"],"explanations":["A still-valid session can survive a password reset unless explicitly invalidated.","An already accepted stolen session may not trigger that new login check.","The attacker's session copy remains valid at the server.","The currently accepted token needs targeted invalidation."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-072","objective":"4.7","concept":"Automation least privilege","prompt":"A script only needs to create incident tickets and read asset metadata, but its API token can delete users and change firewall policies. Which change BEST limits unintended impact?","options":["Keep the broad token in a vault without changing its permissions","Issue a token limited to the script's required operations","Restrict script editing but allow its token every administrative API","Require a longer token value while retaining identical scopes"],"explanations":["Secure storage helps but does not limit actions if the script misuses the token.","Scoped authorization constrains both coding mistakes and token compromise.","Coding mistakes and token compromise still have excessive authority.","Token entropy does not limit authorized API operations."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-073","objective":"4.7","concept":"Automation idempotence","prompt":"A network outage causes a provisioning workflow to retry. Each retry creates another privileged account for the same request. Which property is MOST needed?","options":["Roll back only the last duplicate while leaving earlier duplicate accounts","Use exponential backoff without checking whether the account already exists","Idempotent processing tied to a unique request identifier","Log each retry as a new independent provisioning request"],"explanations":["Partial cleanup does not make repeated requests converge safely.","Delays reduce frequency but still permit duplicates on each retry.","Repeated execution should converge on the same intended result rather than duplicate accounts.","Treating retries as new work causes the duplication rather than preventing it."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-074","objective":"4.8","concept":"Evidence acquisition integrity","prompt":"An investigator hashes a source drive and a forensic image, records the acquisition method, and works only on the image. What is the PRIMARY purpose of the hash comparison?","options":["Establish a complete chain of custody without recording transfers","Establish the suspect's authorship of every recovered file","Prove the investigator had authority to seize the drive","Demonstrate that the image matches the acquired source data"],"explanations":["Matching hashes do not document possession and handling history.","Integrity verification does not establish who created the data.","Legal authority is a separate requirement from technical integrity.","Matching hashes support integrity of the copied evidence; they do not establish who committed an act."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-075","objective":"4.8","concept":"Recovery criteria and monitoring","prompt":"A restored system is malware-free, but its vulnerable service configuration matches the one exploited earlier. What should happen before reconnecting it to production?","options":["Correct or mitigate the entry weakness and validate the recovery criteria","Reconnect once the antivirus scan is clean and fix configuration next quarter","Restore an older backup with the same vulnerable configuration","Disable logging to reduce the chance of false positives during restart"],"explanations":["A clean image can be reinfected if the original exposure remains.","The known entry weakness can allow immediate reinfection.","An older clean state still retains the known exposure.","That reduces visibility without fixing the vulnerability."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-076","objective":"4.8","concept":"Lessons learned ownership","prompt":"A containment decision took 90 minutes because the on-call contact list named an unavailable employee. Which follow-up BEST demonstrates that the process gap was actually corrected?","options":["Update the contact's name in the plan but do not test availability","Update assigned coverage and successfully exercise the escalation path","Purchase a second alerting dashboard that uses the same stale contacts","Set a faster response target without changing coverage or validation"],"explanations":["The document can still fail operationally without validated coverage.","A tested path establishes that the documented ownership can work during a future incident.","Duplicate tools preserve the underlying escalation defect.","A target alone does not enable the team to meet it."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-077","objective":"4.8","concept":"Threat hunting versus incident declaration","prompt":"Threat intelligence describes a new persistence pattern. No alert has fired locally. Analysts proactively search endpoints for that pattern. Which activity BEST fits?","options":["Vulnerability scanning","Reactive alert triage","Threat hunting","Eradication"],"explanations":["The goal is finding adversary persistence, not just identifying exploitable weaknesses.","No alert has fired; the team is proactively testing a hypothesis.","The team is hypothesis-driven and proactive rather than responding only to an existing alert.","There is not yet a confirmed local artifact to remove."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-078","objective":"4.9","concept":"Deny log inference","prompt":"A proxy logs a completed 200 response with 8 MB uploaded to a file-sharing service. Endpoint logs show archive creation just before it. What remains unproven from these two records alone?","options":["Whether the proxy observed the transfer at all","Whether an upload to the service completed according to the proxy","Whether an archive was created before that upload","The specific contents and sensitivity of the uploaded archive"],"explanations":["The supplied transfer record establishes that observation.","The provided proxy record explicitly records a completed response and uploaded bytes.","The endpoint record and stated sequence establish archive creation beforehand.","The sequence supports investigating an upload, but metadata alone does not establish which records it contained."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-079","objective":"4.9","concept":"Flow versus packet evidence","prompt":"Flow records show a 4 GB transfer from a server to an external host. Investigators need to determine which document contents were sent. What is the key limitation?","options":["Flow metadata alone does not contain the transferred application content","Flow metadata proves exfiltration whenever total bytes exceed normal daily usage","Flow records inherently include plaintext payloads from encrypted sessions","Knowing the destination and port identifies the exact document transmitted"],"explanations":["Volume and endpoints establish a transfer pattern, not the actual document bytes.","An anomaly warrants investigation but does not establish content or intent alone.","They describe flows, not decrypted application contents.","Many different documents can use the same connection endpoints."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-080","objective":"4.9","concept":"Cross-source sequence reconstruction","prompt":"VPN logs show a login at 10:02, endpoint logs show archive creation at 10:07, and proxy logs show a large upload at 10:09. Times are synchronized. What additional link is MOST important before treating these as one actor's sequence?","options":["Assume the same minute range proves the same user and device","Correlate identities, device/session identifiers, and destinations across the records","Use only the event with the largest byte count and discard the other records","Combine every event sharing one department's public NAT address"],"explanations":["Temporal proximity alone is insufficient to establish linkage.","Temporal proximity alone is weaker than linking the same subject and activity across sources.","That removes context needed to reconstruct the sequence.","Multiple users and systems can share an egress address."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-081","objective":"5.1","concept":"Policy versus technical authority","prompt":"An engineer can configure a new data-sharing rule but lacks authority to decide whether external sharing is permitted. Who should establish the governing requirement?","options":["The external partner's account manager acting without internal approval","The implementation engineer solely because they can change the setting","The accountable business/security governance authority with data-owner input","The software vendor's default access profile"],"explanations":["A recipient cannot authorize the organization's internal data-handling policy.","Technical ability does not automatically confer authority to set acceptable sharing risk.","Technical implementation must follow authorized policy and ownership decisions.","Defaults are not an organization-specific authorization decision."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-082","objective":"5.1","concept":"Custodian versus owner implementation","prompt":"A database team is instructed to implement a retention period chosen by an authorized records owner. Which responsibility belongs MOST directly to the database team in its custodian role?","options":["Reclassify the records to exempt them from the owner's retention decision","Approve new uses of the records without referring to the accountable owner","Independently reduce the retention period whenever storage is low","Configure and verify retention controls according to the approved requirement"],"explanations":["Classification changes need appropriate authority and evidence.","Business-use decisions exceed the stated custody assignment.","Operational convenience does not authorize a different requirement.","Custodians implement and operate handling controls defined by accountable authorities."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-083","objective":"5.1","concept":"Exception versus standard change","prompt":"Five teams independently request the same permanent deviation from an outdated security standard. Each exception has been renewed for two years. What is the BEST governance response?","options":["Review and update the standard through the authorized process using current risk evidence","Renew all exceptions permanently without reassessing their shared rationale","Remove all mandatory requirements and let teams choose their own controls","Mark the old standard compliant because every team has a workaround"],"explanations":["Repeated permanent deviations suggest the baseline itself needs a formal reassessment.","That perpetuates the mismatch instead of reviewing the baseline.","This abandons consistent accountable governance.","A workaround is not necessarily compliance with the existing standard."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-084","objective":"5.1","concept":"External requirement mapping","prompt":"Two business units follow different local privacy requirements while sharing one corporate security program. What approach BEST supports consistent governance?","options":["Use the least restrictive local rule as the global baseline without checking applicability","Maintain a common baseline and map additional applicable local obligations","Apply the stricter-looking rule without assessing conflicts or local applicability","Let each administrator choose requirements separately at deployment time"],"explanations":["That can leave a unit below its own applicable requirements.","A shared baseline can coexist with stricter or different jurisdiction-specific requirements.","Requirements need mapping, not a simplistic assumption that one rule always satisfies both.","Ad hoc choices lack consistent governance and legal assessment."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-085","objective":"5.2","concept":"Residual versus inherent risk","prompt":"Before controls, a risk is rated high. After segmentation and monitoring, the assessed exposure is moderate and formally accepted by the authorized owner. What is the moderate exposure called?","options":["Transferred risk","Inherent risk","Residual risk","Avoided risk"],"explanations":["No transfer arrangement is described; controls reduced the exposure.","Inherent risk describes exposure before the relevant controls.","Residual risk remains after controls are applied.","The risky activity continues, so the exposure was not eliminated by avoidance."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-086","objective":"5.2","concept":"Business impact prioritization","prompt":"Two applications have similar technical vulnerabilities. One supports payroll due today; the other stores reproducible training examples. Which analysis BEST explains why their restoration priorities may differ?","options":["A threat-intelligence report focused only on exploit availability","A vulnerability severity ranking with no business context","An asset purchase-price comparison alone","Business impact analysis"],"explanations":["Exploitability informs risk but does not alone define business recovery priorities.","Technical severity does not capture today's payroll deadline and operational consequences.","Purchase cost can differ from interruption impact.","A BIA evaluates disruption consequences and recovery priorities for business functions."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-087","objective":"5.2","concept":"Exposure factor interpretation","prompt":"A risk model uses a $240,000 asset, 40% exposure factor, and 0.5 annual event rate. A tested safeguard lowers only the exposure factor to 10%. What annual loss reduction does the model predict?","options":["$36,000","$72,000","$12,000","$48,000"],"explanations":["Original ALE is $48,000; new ALE is $12,000. The difference is $36,000.","That is the reduction per event, before applying the 0.5 annual rate.","That is the new annual loss, not the reduction from the original value.","That is the original annual loss; the safeguard does not eliminate all modeled loss."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-088","objective":"5.2","concept":"Risk avoidance versus mitigation","prompt":"An organization cancels a planned service that would collect biometric data because it does not want the associated exposure. Which treatment BEST fits?","options":["Mitigation","Avoidance","Transfer","Acceptance"],"explanations":["Mitigation would continue the activity while reducing its likelihood or impact.","The organization stops the activity that would create the specified risk.","No other party has assumed a covered portion of the consequences.","Acceptance would retain the activity and knowingly tolerate its risk."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-089","objective":"5.2","concept":"Risk acceptance authority","prompt":"A project lead wants to accept a high-impact risk beyond the lead's delegated limit to meet a deadline. What is the BEST next action?","options":["Reduce the documented impact rating solely to fit the lead's approval limit","Accept through the project lead and seek senior approval after delivery","Escalate the documented residual risk to the authority permitted to accept it","Assign the risk to the vendor and assume it is transferred automatically"],"explanations":["That changes the assessment without supporting evidence.","The lead lacks current delegated authority for that level of risk.","Risk acceptance must stay within defined decision rights.","A register edit does not establish a contractual transfer or authorized acceptance."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-090","objective":"5.3","concept":"Right-to-audit versus NDA","prompt":"A supplier will handle sensitive data. The customer needs a contractual ability to inspect relevant control evidence during the relationship. Which provision MOST directly supports this?","options":["An exclusivity clause for future purchases","Nondisclosure agreement only","Uptime service-level agreement only","Right-to-audit clause"],"explanations":["Commercial exclusivity does not authorize an audit.","Confidentiality restrictions do not inherently grant inspection access.","Availability targets do not necessarily establish control-evidence rights.","It establishes the agreed ability to assess or inspect specified evidence and controls."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-091","objective":"5.3","concept":"Service-level metric definition","prompt":"A contract promises 99.9% uptime but excludes every outage caused by the supplier's own maintenance without limiting that exclusion. What is the MOST important clarification?","options":["Define measurement, allowed exclusions, maintenance limits, and remedies","Increase uptime to 99.99% but retain unlimited maintenance exclusions","Measure only unplanned outages and let the supplier classify outages without constraints","Replace availability measurement with the count of support tickets closed"],"explanations":["A headline target is weak without clear calculation boundaries and accountability.","A stricter number can still be undermined by unlimited excluded downtime.","Unbounded classification discretion preserves the ambiguity.","Ticket closure does not directly establish actual service availability."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-092","objective":"5.3","concept":"Supplier reassessment trigger","prompt":"A previously approved vendor moves sensitive processing to a new subcontractor and region. What is the BEST response?","options":["Rely on the old assessment because the original vendor name is unchanged","Reassess the changed data flow, subcontractor controls, and contractual obligations","Review only the price change in the next invoice","Accept a new region solely because data remains encrypted in transit"],"explanations":["The processing entities and location changed despite the same contracting name.","Material changes can invalidate assumptions from the original due diligence.","Commercial cost does not establish processing compliance or control adequacy.","Transport encryption does not resolve location and subcontractor obligations."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-093","objective":"5.4","concept":"Attestation versus evidence","prompt":"A manager signs a quarterly statement asserting compliance, but no supporting control tests are retained. What is the MAIN assurance limitation?","options":["A policy document alone fully substitutes for the missing quarterly evidence","The attestation establishes operating effectiveness without any supporting tests","The assertion lacks supporting evidence of control operation","An absence of reported incidents conclusively validates the manager's claim"],"explanations":["Written intent does not demonstrate operation during the period.","An assertion is not itself proof that controls operated.","Attestation is a claim; evidence is needed to substantiate it.","Undetected problems and ineffective controls may exist without reported incidents."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-094","objective":"5.4","concept":"Privacy breach notification process","prompt":"An incident may involve regulated personal data, but scope is still being investigated. Which approach BEST supports notification compliance?","options":["Let the technical team select a deadline based on a different prior incident","Delay legal/privacy involvement until the final forensic report is complete","Send one standard public notification without assessing affected people or obligations","Engage the designated legal/privacy process promptly and track applicable decision deadlines"],"explanations":["Applicability can differ by data, jurisdiction, contract, and incident facts.","That can miss applicable time-sensitive assessment and notification obligations.","A generic unverified disclosure is not a substitute for the required decision process.","Uncertainty should be assessed within the established process rather than used to ignore time-sensitive obligations."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-095","objective":"5.5","concept":"Rules of engagement boundaries","prompt":"A red-team engagement authorizes social engineering but explicitly excludes contacting emergency services. An attack idea would require such a call. What should the team do?","options":["Exclude that technique unless the authorized engagement terms are formally changed","Proceed under the broad social-engineering permission despite the listed exclusion","Seek permission from an employee outside the designated engagement authorities","Make the call outside normal business hours to reduce disruption"],"explanations":["A general permission does not override an explicit prohibition.","The specific prohibition constrains the broad permission.","That person may lack authority to amend the rules.","Timing does not remove the explicit prohibition."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-096","objective":"5.5","concept":"Active versus passive reconnaissance","prompt":"An assessor compares public job postings, certificate transparency records, and published documents without sending probes to the target's systems. Which activity BEST fits?","options":["An active port-discovery scan","Passive reconnaissance using open-source information","A credentialed configuration assessment","An exploitation attempt using public source code"],"explanations":["The assessor is not sending probes to the target systems.","The assessor gathers publicly available information without directly probing the target systems.","No authorized host login or configuration inspection is described.","Gathering public information is not execution of an exploit."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-097","objective":"5.5","concept":"Audit finding closure","prompt":"A team says it corrected an access-review finding. The auditor must determine whether to close it. Which evidence is MOST useful?","options":["The administrator's unsupported statement that permissions look appropriate","The new policy and an unsigned schedule for future reviews","A completed review sample showing approvals, removals, and follow-through","A report listing current users with no reviewer decisions or removal evidence"],"explanations":["A specific finding needs verifiable execution and outcomes.","Intent and scheduling do not demonstrate completed operation.","Evidence of execution and resulting corrections supports closure.","A raw list is not proof that an access review occurred and was acted on."],"correct":2,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-098","objective":"5.6","concept":"Simulation metric denominator","prompt":"A phishing exercise's raw click count falls from 40 to 20, but the tested population also falls from 400 to 100. What is the correct interpretation?","options":["The results prove training had no effect on any participant","The click rate improved by half","The click rate remained 10%","The click rate worsened from 10% to 20%"],"explanations":["Aggregate rates do not prove individual causal effects.","That compares counts without accounting for population.","Twenty clicks among 100 users is 20%.","Rates require the tested population; the smaller raw count masks a doubled click rate."],"correct":3,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-099","objective":"5.6","concept":"Behavioral anomaly escalation","prompt":"A normally cooperative employee begins bypassing data-handling rules and exporting unusually large files. A colleague notices but has no proof of malicious intent. What is the BEST response?","options":["Report the specific observations through the established security channel","Conclude that malicious intent is established solely by the unusual volume","Wait for a confirmed loss before using the reporting process","Investigate by accessing the employee's accounts without authorization"],"explanations":["Behavioral indicators warrant factual reporting and assessment, not unsupported personal accusations.","The behavior warrants assessment, but does not by itself prove intent.","Prompt factual reporting can enable earlier investigation and prevention.","Colleagues should report observations through process, not exceed their authority."],"correct":0,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"},{"id":"CH2-100","objective":"5.6","concept":"Training transfer assessment","prompt":"Staff can define phishing correctly on a quiz but still follow urgent payment-change requests without independent verification. Which exercise BEST tests the missing skill?","options":["Repeat a definition-only phishing quiz until every employee scores perfectly","A realistic payment-change scenario requiring selection of the verification action","Measure only attendance at a longer payment-fraud presentation","Ask staff to rate how confident they feel without practicing the action"],"explanations":["Terminology recall is already demonstrated but has not transferred to the decision.","Applied practice tests transfer of knowledge to the observed risky decision.","Attendance does not demonstrate a performed verification skill.","Self-reported confidence does not establish correct application."],"correct":1,"examId":"challenge-2","revision":"challenge-v13","type":"mcq","provenance":"Original practice"}]}];
